package com.alessandro.tedesco.i18n

/**
 * Runtime translation layer (IT -> EN).
 *
 * The UI was originally written in Italian with inline literals. Every literal that
 * needs a translation is wrapped in [t]; when the interface language is English the
 * map below replaces it. When the language is Italian [t] returns the input unchanged,
 * so the Italian text remains the single source of truth.
 */
