    private fun esattoChunk1(): Map<String, String> = mapOf(
            "Il dativo è il caso del complemento di termine: risponde a Wem? (a chi?)." to "The dative is the case of the indirect object: it answers Wem? (to whom?).",
            "Gli articoli cambiano: der -> dem, die -> der, das -> dem; al plurale den + -n sul sostantivo." to "Articles change: der -> dem, die -> der, das -> dem; in the plural den + -n on the noun.",
            "Gli articoli indeterminativi e i possessivi prendono le desinenze del dativo: einem/einer/einem, meinem/meiner/meinem, deinem/deiner/deinem, seinem/seiner/seinem." to "Indefinite articles and possessives take dative endings: einem/einer/einem, meinem/meiner/meinem, deinem/deiner/deinem, seinem/seiner/seinem.",
            "Al plurale il dativo è den + -n sul sostantivo (den Kindern); anche kein diventa keinen (keinen Kindern)." to "In the plural the dative is den + -n on the noun (den Kindern); kein also becomes keinen (keinen Kindern).",
            "I pronomi al dativo sono mir, dir, ihm, ihr, ihm, uns, euch, ihnen." to "Dative pronouns are mir, dir, ihm, ihr, ihm, uns, euch, ihnen.",
            "Molti verbi reggono il dativo: helfen, danken, gefallen, gehören, passen, schmecken, antworten, folgen. Anche le preposizioni aus, bei, mit, nach, seit, von, zu reggono il dativo." to "Many verbs take the dative: helfen, danken, gefallen, gehören, passen, schmecken, antworten, folgen. The prepositions aus, bei, mit, nach, seit, von, zu also take the dative.",
            "Al dativo plurale il sostantivo aggiunge spesso -n: den Kindern." to "In the dative plural the noun often adds -n: den Kindern.",
            "Al dativo cambiano tutti i generi: maschile e neutro -em, femminile -er, plurale -en." to "In the dative all genders change: masculine and neuter -em, feminine -er, plural -en.",
            "Aiuto l'uomo." to "I help the man.",
            "Il libro appartiene alla donna." to "The book belongs to the woman.",
            "Ringraziamo i bambini." to "We thank the children.",
            "Questo mi piace." to "I like this.",
            "Vado in autobus." to "I go by bus.",
            "helfen regge il dativo: der Mann -> dem Mann." to "helfen takes the dative: der Mann -> dem Mann.",
            "danken vuole il dativo diretto, senza für: ich danke dir." to "danken takes the dative directly, without für: ich danke dir.",
            "Auto è neutro; al dativo l'articolo è dem: mit dem Auto." to "Auto is neuter; in the dative the article is dem: mit dem Auto.",
            "Dativo: dem, der, dem, den + -n. Possessivi: meinem, meiner, meinem, meinen. Pronomi: mir, dir, ihm, ihr, ihm, uns, euch, ihnen." to "Dative: dem, der, dem, den + -n. Possessives: meinem, meiner, meinem, meinen. Pronouns: mir, dir, ihm, ihr, ihm, uns, euch, ihnen.",
            "helfen regge il dativo: dem Mann." to "helfen takes the dative: dem Mann.",
            "Frau è femminile; al dativo l'articolo è der." to "Frau is feminine; in the dative the article is der.",
            "Lehrer è maschile singolare; al dativo: dem Lehrer." to "Lehrer is masculine singular; in the dative: dem Lehrer.",
            "Plurale al dativo: den Kindern." to "Plural in the dative: den Kindern.",
            "gefallen regge il dativo: mir." to "gefallen takes the dative: mir.",
            "mit regge il dativo; Bus è maschile: dem Bus." to "mit takes the dative; Bus is masculine: dem Bus.",
            "die Schweiz è femminile; al dativo: aus der Schweiz." to "die Schweiz is feminine; in the dative: aus der Schweiz.",
            "Plurale al dativo: bei den Eltern." to "Plural in the dative: bei den Eltern.",
            "Il pronome dativo di ich è mir." to "The dative pronoun of ich is mir.",
            "dem Mann maschile diventa ihm." to "masculine dem Mann becomes ihm.",
            "der Frau femminile diventa ihr." to "feminine der Frau becomes ihr.",
            "Traduci: «Mi piace Berlino.»" to "Translate: 'I like Berlin.'",
            "gefallen + dativo: Berlin gefällt mir." to "gefallen + dative: Berlin gefällt mir.",
            "Usa il verbo gefallen." to "Use the verb gefallen.",
            "Il Präteritum è il passato semplice; si usa soprattutto nello scritto, nei racconti e nelle notizie. Nel parlato prevale spesso il Perfekt." to "The Präteritum is the simple past; it is mainly used in writing, stories and news. In speech, Perfekt is often preferred.",
            "I verbi regolari aggiungono -te alla radice: machen -> machte, arbeiten -> arbeitete." to "Regular verbs add -te to the stem: machen -> machte, arbeiten -> arbeitete.",
            "I verbi irregolari cambiano la radice e prendono le desinenze senza -te: gehen -> ging, lesen -> las, kommen -> kam." to "Irregular verbs change the stem and take endings without -te: gehen -> ging, lesen -> las, kommen -> kam.",
            "sein diventa war, haben diventa hatte, werden diventa wurde." to "sein becomes war, haben becomes hatte, werden becomes wurde.",
            "I modali al Präteritum sono konnte, musste, wollte, durfte, sollte, mochte." to "Modals in Präteritum are konnte, musste, wollte, durfte, sollte, mochte.",
            "Nei verbi regolari si sente chiaramente la -te; negli irregolari cambia la vocale della radice." to "In regular verbs you clearly hear -te; in irregular verbs the stem vowel changes.",
            "Ieri ero al cinema." to "Yesterday I was at the cinema.",
            "Non avevamo tempo." to "We didn't have time.",
            "Andò a Berlino." to "He went to Berlin.",
            "Lei lesse il libro." to "She read the book.",
            "Non potevo venire." to "I couldn't come.",
            "gehen è irregolare: il Präteritum è ging, non gehte." to "gehen is irregular: the Präteritum is ging, not gehte.",
            "Il Präteritum non si forma con haben + participio: è una forma verbale unica." to "The Präteritum is not formed with haben + participle: it is a single verb form.",
            "La terza persona singolare di sein al Präteritum è war." to "The third person singular of sein in Präteritum is war.",
            "Regolari: radice + te. Irregolari: nuova radice + desinenze. sein: war, haben: hatte." to "Regular: stem + te. Irregular: new stem + endings. sein: war, haben: hatte.",
            "sein al Präteritum: ich war." to "sein in Präteritum: ich war.",
            "haben al Präteritum: wir hatten." to "haben in Präteritum: wir hatten.",
            "gehen è irregolare: er ging." to "gehen is irregular: er ging.",
            "lesen al Präteritum: sie las." to "lesen in Präteritum: sie las.",
            "arbeiten al Präteritum: du arbeitetest." to "arbeiten in Präteritum: du arbeitetest.",
            "machen è regolare: ich machte." to "machen is regular: ich machte.",
            "kommen è irregolare: wir kamen." to "kommen is irregular: wir kamen.",
            "sein al Präteritum: er war." to "sein in Präteritum: er war.",
            "Trasforma al Präteritum: Ich gehe nach Hause." to "Change to Präteritum: Ich gehe nach Hause.",
            "gehen -> ging." to "gehen -> ging.",
            "Trasforma al Präteritum: Wir haben Zeit." to "Change to Präteritum: Wir haben Zeit.",
            "haben -> hatten." to "haben -> hatten.",
            "können al Präteritum: sie konnte." to "können in Präteritum: sie konnte.",
            "Traduci: «Ieri ho comprato un libro.»" to "Translate: 'Yesterday I bought a book.'",
            "kaufen al Präteritum: kaufte. È accettabile anche il Perfekt nel parlato." to "kaufen in Präteritum: kaufte. Perfekt is also acceptable in speech.",
            "Usa Gestern e il Präteritum di kaufen." to "Use Gestern and the Präteritum of kaufen.",

