    private fun esattoChunk2(): Map<String, String> = mapOf(
            "I verbi riflessivi hanno un pronome che rimanda al soggetto: mich, dich, sich, uns, euch, sich." to "Reflexive verbs have a pronoun that refers back to the subject: mich, dich, sich, uns, euch, sich.",
            "La maggior parte dei riflessivi usa il pronome all'accusativo; alcuni verbi vogliono il dativo: Ich wasche mir die Hände." to "Most reflexive verbs use the pronoun in the accusative; some verbs take the dative: Ich wasche mir die Hände.",
            "Verbi frequenti: sich freuen, sich interessieren für, sich waschen, sich treffen, sich beeilen, sich erholen, sich setzen, sich fühlen." to "Common verbs: sich freuen, sich interessieren für, sich waschen, sich treffen, sich beeilen, sich erholen, sich setzen, sich fühlen.",
            "Il pronome riflessivo sta di solito dopo il verbo coniugato e prima degli altri complementi: Ich freue mich auf den Urlaub." to "The reflexive pronoun usually comes after the conjugated verb and before other complements: Ich freue mich auf den Urlaub.",
            "In tedesco alcuni verbi sono riflessivi anche se in italiano non lo sono: sich beeilen (affrettarsi), sich erholen (riposarsi)." to "In German some verbs are reflexive even if they are not in English: sich beeilen (to hurry), sich erholen (to rest).",
            "Non vedo l'ora che arrivino le vacanze." to "I'm looking forward to the holidays.",
            "Ti interessi di musica." to "You're interested in music.",
            "Ci incontriamo alle 8." to "We meet at 8.",
            "Si riposa in giardino." to "She rests in the garden.",
            "Mi lavo le mani." to "I wash my hands.",
            "sich freuen richiede il pronome riflessivo: ich freue mich." to "sich freuen requires the reflexive pronoun: ich freue mich.",
            "Con una parte del corpo il riflessivo è al dativo: mir die Hände." to "With a body part the reflexive is in the dative: mir die Hände.",
            "Con wir il pronome riflessivo è uns." to "With wir the reflexive pronoun is uns.",
            "Riflessivi: mich, dich, sich, uns, euch, sich. Con parti del corpo spesso il dativo: mir." to "Reflexives: mich, dich, sich, uns, euch, sich. With body parts often dative: mir.",
            "sich freuen all'accusativo: ich freue mich." to "sich freuen in the accusative: ich freue mich.",
            "Con du il riflessivo è dich." to "With du the reflexive is dich.",
            "Con er il riflessivo è sich." to "With er the reflexive is sich.",
            "Con wir il riflessivo è uns." to "With wir the reflexive is uns.",
            "Con sie plurale il riflessivo è sich." to "With sie plural the reflexive is sich.",
            "Con una parte del corpo il riflessivo è al dativo: mir." to "With a body part the reflexive is in the dative: mir.",
            "Con sie singolare il riflessivo è sich." to "With sie singular the reflexive is sich.",
            "Con ihr il riflessivo è euch." to "With ihr the reflexive is euch.",
            "sich freuen: ich freue mich auf ..." to "sich freuen: ich freue mich auf ...",
            "sich treffen: wir treffen uns." to "sich treffen: wir treffen uns.",
            "Traduci: «Mi riposo un po'.»" to "Translate: 'I'm resting a bit.'",
            "sich erholen: ich erhole mich; ein bisschen = un po'." to "sich erholen: ich erhole mich; ein bisschen = a bit.",
            "Usa sich erholen." to "Use sich erholen.",
            "Nella frase subordinata il verbo coniugato va alla fine: Ich bleibe zu Hause, weil ich krank bin." to "In a subordinate clause the conjugated verb goes to the end: Ich bleibe zu Hause, weil ich krank bin.",
            "Le congiunzioni più comuni sono weil (perché), dass (che), wenn (se/quando), obwohl (sebbene), als (quando, per un evento passato), während (mentre), bevor (prima che), nachdem (dopo che), damit (affinché), ob (se, nelle domande indirette)." to "The most common conjunctions are weil (because), dass (that), wenn (if/when), obwohl (although), als (when, for a past event), während (while), bevor (before), nachdem (after), damit (so that), ob (whether, in indirect questions).",
            "Se la subordinata viene prima, la principale comincia dopo la virgola con il verbo: Weil ich krank bin, bleibe ich zu Hause." to "If the subordinate clause comes first, the main clause starts after the comma with the verb: Weil ich krank bin, bleibe ich zu Hause.",
            "Espressioni utili: am Ende des Satzes (alla fine della frase), am Anfang (all'inizio)." to "Useful expressions: am Ende des Satzes (at the end of the sentence), am Anfang (at the beginning).",
            "weil e denn significano entrambi «perché», ma denn è coordinante e lascia il verbo in seconda posizione: Ich bleibe zu Hause, denn ich bin krank." to "weil and denn both mean 'because', but denn is coordinating and leaves the verb in second position: Ich bleibe zu Hause, denn ich bin krank.",
            "wenn si usa per presente, futuro o eventi ripetuti; als per un singolo evento nel passato: Als ich klein war, ..." to "wenn is used for present, future or repeated events; als for a single event in the past: Als ich klein war, ...",
            "Dopo tutte queste congiunzioni il verbo coniugato va in fondo." to "After all these conjunctions the conjugated verb goes to the end.",
            "Resto a casa perché sono malato." to "I stay home because I'm sick.",
            "Dice che non ha tempo." to "He says that he has no time.",
            "Quando ero piccolo, abitavo a Roma." to "When I was little, I lived in Rome.",
            "Sebbene piova, andiamo a passeggiare." to "Although it's raining, we're going for a walk.",
            "Non so se viene." to "I don't know if he's coming.",
            "Dopo weil il verbo coniugato va alla fine." to "After weil the conjugated verb goes to the end.",
            "Dopo weil il verbo coniugato va alla fine: ... weil ich krank bin." to "After weil the conjugated verb goes to the end: ... weil ich krank bin.",
            "Nella subordinata il verbo war va alla fine." to "In the subordinate clause the verb war goes to the end.",
            "Dopo dass il verbo coniugato va alla fine: ... morgen kommt." to "After dass the conjugated verb goes to the end: ... morgen kommt.",
            "Subordinata: verbo alla fine. weil, dass, wenn, obwohl, als, während, bevor, nachdem, ob." to "Subordinate clause: verb at the end. weil, dass, wenn, obwohl, als, während, bevor, nachdem, ob.",
            "weil introduce una subordinata con il verbo alla fine: ... weil ich krank bin." to "weil introduces a subordinate clause with the verb at the end: ... weil ich krank bin.",
            "dass introduce una frase completiva: ... dass er keine Zeit hat." to "dass introduces a complement clause: ... dass er keine Zeit hat.",
            "Per un singolo evento passato si usa als." to "For a single past event, use als.",
            "Per un evento presente/futuro si usa wenn." to "For a present/future event, use wenn.",
            "Il motivo si esprime con weil: ... weil sie ... will." to "The reason is expressed with weil: ... weil sie ... will.",
            "Dopo dass il verbo coniugato va alla fine: ... er kommt." to "After dass the conjugated verb goes to the end: ... er kommt.",
            "La subordinata causale introdotta da weil: Weil ich krank bin, ..." to "The causal subordinate clause introduced by weil: Weil ich krank bin, ...",
            "La causa si esprime con weil; il verbo hat è alla fine." to "The cause is expressed with weil; the verb hat is at the end.",
            "weil richiede il verbo alla fine: ... weil ich müde bin." to "weil requires the verb at the end: ... weil ich müde bin.",
            "Unisci con weil: Ich bleibe zu Hause. Ich bin müde." to "Join with weil: Ich bleibe zu Hause. Ich bin müde.",
            "Unisci con dass: Er sagt. Er kommt morgen." to "Join with dass: Er sagt. Er kommt morgen.",
            "Dopo dass il verbo kommt va alla fine." to "After dass the verb kommt goes to the end.",
            "Un evento passato singolo: als ich in Berlin war." to "A single past event: als ich in Berlin war.",
            "Traduci: «Penso che tu abbia ragione.»" to "Translate: 'I think you're right.'",
            "dass + verbo alla fine: ... dass du recht hast." to "dass + verb at the end: ... dass du recht hast.",
            "Usa dass e recht haben." to "Use dass and recht haben.",

