            "La frase relativa descrive un sostantivo e si mette tra virgole; il verbo coniugato va alla fine." to "The relative clause describes a noun and is placed between commas; the conjugated verb goes to the end.",
            "Il pronome relativo prende genere e numero dall'antecedente, ma il caso dalla sua funzione nella frase relativa." to "The relative pronoun takes gender and number from the antecedent, but case from its function in the relative clause.",
            "Nominativo: der/die/das/die; accusativo: den/die/das/die; dativo: dem/der/dem/denen; genitivo: dessen (maschile/neutro) e deren (femminile/plurale)." to "Nominative: der/die/das/die; accusative: den/die/das/die; dative: dem/der/dem/denen; genitive: dessen (masculine/neuter) and deren (feminine/plural).",
            "Se il pronome relativo è preceduto da una preposizione, la preposizione resta davanti: Der Mann, mit dem ich spreche." to "If the relative pronoun is preceded by a preposition, the preposition stays in front: Der Mann, mit dem ich spreche.",
            "Se il pronome relativo � preceduto da una preposizione, la preposizione resta davanti: Der Mann, mit dem ich spreche." to "If the relative pronoun is preceded by a preposition, the preposition stays in front: Der Mann, mit dem ich spreche.",
