            "L'aggettivo davanti al sostantivo prende una desinenza; dopo il verbo (predicativo) resta invariato: Das Auto ist neu." to "The adjective before a noun takes an ending; after the verb (predicative) it stays unchanged: Das Auto ist neu.",
            "Dopo l'articolo determinativo (der/die/das) si usa la declinazione debole: al nominativo singolare -e, negli altri casi spesso -en." to "After the definite article (der/die/das) the weak declension is used: in nominative singular -e, in other cases often -en.",
            "Dopo l'articolo indeterminativo (ein/eine/ein), kein e i possessivi si usa la declinazione mista: il maschile e il neutro al nominativo prendono -er/-es, gli altri casi spesso -en." to "After the indefinite article (ein/eine/ein), kein and possessives the mixed declension is used: masculine and neuter nominative take -er/-es, other cases often -en.",
            "Senza articolo si usa la declinazione forte: l'aggettivo deve mostrare da solo il caso e il genere." to "Without an article the strong declension is used: the adjective must show case and gender on its own.",
            "Le tabelle vanno imparate per blocchi: prima il nominativo e l'accusativo, poi il dativo e il genitivo." to "Learn the tables in blocks: first nominative and accusative, then dative and genitive.",
            "Al nominativo maschile e neutro l'aggettivo prende la desinenza che mancherebbe all'articolo: -er, -es." to "In the masculine and neuter nominative the adjective takes the ending the article would lack: -er, -es.",
            "La desinenza forte è quella che rende riconoscibile il caso anche senza articolo." to "The strong ending is the one that makes the case recognisable even without an article.",
            "La desinenza forte � quella che rende riconoscibile il caso anche senza articolo." to "The strong ending is the one that makes the case recognisable even without an article.",
            "L'uomo anziano legge un giornale." to "The old man reads a newspaper.",
            "Vedo il cane piccolo." to "I see the little dog.",
            "Questo è un buon film." to "This is a good film.",
            "Questo � un buon film." to "This is a good film.",
            "Con la nuova auto vado a Berlino." to "I'm going to Berlin with the new car.",
            "L'acqua fredda è sana." to "Cold water is healthy.",
            "L'acqua fredda � sana." to "Cold water is healthy.",
            "Auto è neutro: das neue Auto." to "Auto is neuter: das neue Auto.",
            "Auto � neutro: das neue Auto." to "Auto is neuter: das neue Auto.",
            "Dopo ein, al nominativo neutro, l'aggettivo prende -es: ein neues Auto." to "After ein, in the neuter nominative, the adjective takes -es: ein neues Auto.",
            "Dopo den, all'accusativo maschile, l'aggettivo prende -en." to "After den, in the masculine accusative, the adjective takes -en.",
            "Dopo der/die/das: -e/-en. Dopo ein/kein: -er/-e/-es. Senza articolo: desinenza forte." to "After der/die/das: -e/-en. After ein/kein: -er/-e/-es. Without article: strong ending.",
            "Dopo der, nominativo maschile, l'aggettivo prende -e: der alte Mann." to "After der, masculine nominative, the adjective takes -e: der alte Mann.",
            "Dopo die, nominativo femminile, l'aggettivo prende -e: die schöne Frau." to "After die, feminine nominative, the adjective takes -e: die schöne Frau.",
            "Dopo die, nominativo femminile, l'aggettivo prende -e: die sch�ne Frau." to "After die, feminine nominative, the adjective takes -e: die schöne Frau.",
            "Dopo das, nominativo neutro, l'aggettivo prende -e: das kleine Kind." to "After das, neuter nominative, the adjective takes -e: das kleine Kind.",
            "Dopo ein, nominativo neutro, l'aggettivo prende -es: ein neues Auto." to "After ein, neuter nominative, the adjective takes -es: ein neues Auto.",
            "Dopo den, accusativo maschile, l'aggettivo prende -en: den alten Mann." to "After den, masculine accusative, the adjective takes -en: den alten Mann.",
            "Dopo ein, accusativo neutro, l'aggettivo prende -es: ein neues Buch." to "After ein, neuter accusative, the adjective takes -es: ein neues Buch.",
            "Dopo die, plurale, l'aggettivo prende -en: die roten Schuhe." to "After die, plural, the adjective takes -en: die roten Schuhe.",
            "Dopo dem, dativo neutro, l'aggettivo prende -en: mit dem neuen Auto." to "After dem, neuter dative, the adjective takes -en: mit dem neuen Auto.",
            "Inserisci l'aggettivo: Das ist ein / gut / Film." to "Insert the adjective: Das ist ein / gut / Film.",
            "Dopo ein, nominativo maschile, l'aggettivo prende -er: ein guter Film." to "After ein, masculine nominative, the adjective takes -er: ein guter Film.",
            "Inserisci l'aggettivo: Ich sehe den / klein / Hund." to "Insert the adjective: Ich sehe den / klein / Hund.",
            "Senza articolo, nominativo neutro, l'aggettivo prende -es: kaltes Wasser." to "Without article, neuter nominative, the adjective takes -es: kaltes Wasser.",
