            "I connettori coordinanti (und, aber, oder, denn, sondern) non cambiano l'ordine della frase: Ich bleibe zu Hause, denn ich bin krank." to "Coordinating connectors (und, aber, oder, denn, sondern) do not change sentence order: Ich bleibe zu Hause, denn ich bin krank.",
            "I connettori subordinanti (weil, obwohl, wenn, dass, damit, während, bevor, nachdem) mandano il verbo coniugato alla fine." to "Subordinating connectors (weil, obwohl, wenn, dass, damit, während, bevor, nachdem) send the conjugated verb to the end.",
            "I connettori subordinanti (weil, obwohl, wenn, dass, damit, w�hrend, bevor, nachdem) mandano il verbo coniugato alla fine." to "Subordinating connectors (weil, obwohl, wenn, dass, damit, während, bevor, nachdem) send the conjugated verb to the end.",
            "I connettivi avverbiali (deshalb, darum, trotzdem, außerdem, sonst, dann) occupano la prima posizione e richiedono il verbo in seconda: Ich bin krank, deshalb bleibe ich im Bett." to "Adverbial connectors (deshalb, darum, trotzdem, außerdem, sonst, dann) take first position and require the verb in second: Ich bin krank, deshalb bleibe ich im Bett.",
            "I connettivi avverbiali (deshalb, darum, trotzdem, au�erdem, sonst, dann) occupano la prima posizione e richiedono il verbo in seconda: Ich bin krank, deshalb bleibe ich im Bett." to "Adverbial connectors (deshalb, darum, trotzdem, außerdem, sonst, dann) take first position and require the verb in second: Ich bin krank, deshalb bleibe ich im Bett.",
            "sondern si usa dopo una negazione per correggere: Er ist nicht groß, sondern klein." to "sondern is used after a negation to correct: Er ist nicht groß, sondern klein.",
