            "Sebbene piova, andiamo al cinema." to "Although it's raining, we're going to the cinema.",
            "Non imparo solo il tedesco, ma anche lo spagnolo." to "I'm not only learning German, but also Spanish.",
            "weil è subordinante: il verbo coniugato va alla fine." to "weil is subordinating: the conjugated verb goes to the end.",
            "weil � subordinante: il verbo coniugato va alla fine." to "weil is subordinating: the conjugated verb goes to the end.",
            "deshalb occupa la prima posizione; il verbo viene subito dopo." to "deshalb takes first position; the verb comes immediately after.",
            "Dopo una negazione, per correggere si usa sondern." to "After a negation, use sondern to correct.",
            "Coordinanti: ordine normale. Subordinanti: verbo alla fine. Avverbiali: verbo in seconda." to "Coordinating: normal order. Subordinating: verb at the end. Adverbial: verb in second position.",
            "weil introduce la causa e manda il verbo alla fine." to "weil introduces the cause and sends the verb to the end.",
            "deshalb esprime la conseguenza e richiede il verbo in seconda posizione." to "deshalb expresses consequence and requires the verb in second position.",
            "wenn introduce una condizione e manda il verbo alla fine." to "wenn introduces a condition and sends the verb to the end.",
            "Il motivo si esprime con weil." to "The reason is expressed with weil.",
            "La conseguenza si esprime con deshalb + verbo in seconda posizione." to "The consequence is expressed with deshalb + verb in second position.",
            "La causa si esprime con weil; il verbo ist è alla fine." to "The cause is expressed with weil; the verb ist is at the end.",
            "La causa si esprime con weil; il verbo ist � alla fine." to "The cause is expressed with weil; the verb ist is at the end.",
            "Il contrasto si esprime con obwohl; il verbo regnet è alla fine." to "Contrast is expressed with obwohl; the verb regnet is at the end.",
            "Il contrasto si esprime con obwohl; il verbo regnet � alla fine." to "Contrast is expressed with obwohl; the verb regnet is at the end.",
            "Unisci con deshalb: Ich bin krank. Ich bleibe zu Hause." to "Join with deshalb: Ich bin krank. Ich bleibe zu Hause.",
            "deshalb occupa la prima posizione della seconda frase; il verbo bleibe viene dopo." to "deshalb takes first position in the second clause; the verb bleibe comes after.",
            "Unisci con obwohl: Es regnet. Wir gehen spazieren." to "Join with obwohl: Es regnet. Wir gehen spazieren.",
            "obwohl introduce la subordinata con il verbo alla fine; la principale segue con il verbo in seconda posizione." to "obwohl introduces the subordinate clause with the verb at the end; the main clause follows with the verb in second position.",
            "La coppia weder ... noch significa «né ... né»: weder Zeit noch Geld." to "The pair weder ... noch means \"neither ... nor\": weder Zeit noch Geld.",
            "La coppia weder ... noch significa �n� ... n��: weder Zeit noch Geld." to "The pair weder ... noch means \"neither ... nor\": weder Zeit noch Geld.",
            "Scrivi solo la prima parola della coppia." to "Write only the first word of the pair.",
            "Traduci: «Non solo imparo il tedesco, ma anche l'inglese.»" to "Translate: \"I'm not only learning German, but also English.\"",
            "Traduci: �Non solo imparo il tedesco, ma anche l'inglese.�" to "Translate: \"I'm not only learning German, but also English.\"",
            "La coppia nicht nur ... sondern auch collega i due elementi." to "The pair nicht nur ... sondern auch links the two elements.",
            "Usa nicht nur ... sondern auch." to "Use nicht nur ... sondern auch.",
            "Il Konjunktiv II si usa per ipotesi irreali, desideri e richieste cortesi: Wenn ich Zeit hätte, würde ich kommen." to "Konjunktiv II is used for unreal hypotheses, wishes and polite requests: Wenn ich Zeit hätte, würde ich kommen.",
            "Il Konjunktiv II si usa per ipotesi irreali, desideri e richieste cortesi: Wenn ich Zeit h�tte, w�rde ich kommen." to "Konjunktiv II is used for unreal hypotheses, wishes and polite requests: Wenn ich Zeit hätte, würde ich kommen.",
            "Per molti verbi si usa würde + infinito: ich würde kommen, du würdest lernen." to "For many verbs, würde + infinitive is used: ich würde kommen, du würdest lernen.",
            "Per molti verbi si usa w�rde + infinito: ich w�rde kommen, du w�rdest lernen." to "For many verbs, würde + infinitive is used: ich würde kommen, du würdest lernen.",
            "I verbi più frequenti hanno forme proprie: sein -> wäre, haben -> hätte, werden -> würde, können -> könnte, müssen -> müsste, dürfen -> dürfte, wissen -> wüsste." to "The most common verbs have their own forms: sein -> wäre, haben -> hätte, werden -> würde, können -> könnte, müssen -> müsste, dürfen -> dürfte, wissen -> wüsste.",
            "I verbi pi� frequenti hanno forme proprie: sein -> w�re, haben -> h�tte, werden -> w�rde, k�nnen -> k�nnte, m�ssen -> m�sste, d�rfen -> d�rfte, wissen -> w�sste." to "The most common verbs have their own forms: sein -> wäre, haben -> hätte, werden -> würde, können -> könnte, müssen -> müsste, dürfen -> dürfte, wissen -> wüsste.",
            "Nel periodo ipotetico: Wenn ich reich wäre, würde ich reisen. La principale può anche iniziare con dann: Dann würde ich reisen." to "In conditional sentences: Wenn ich reich wäre, würde ich reisen. The main clause can also start with dann: Dann würde ich reisen.",
            "Nel periodo ipotetico: Wenn ich reich w�re, w�rde ich reisen. La principale pu� anche iniziare con dann: Dann w�rde ich reisen." to "In conditional sentences: Wenn ich reich wäre, würde ich reisen. The main clause can also start with dann: Dann würde ich reisen.",
            "Il passato irreale si forma con hätte/wäre + Partizip II: Wenn ich das gewusst hätte, wäre ich gekommen." to "The unreal past is formed with hätte/wäre + Partizip II: Wenn ich das gewusst hätte, wäre ich gekommen.",
            "Il passato irreale si forma con h�tte/w�re + Partizip II: Wenn ich das gewusst h�tte, w�re ich gekommen." to "The unreal past is formed with hätte/wäre + Partizip II: Wenn ich das gewusst hätte, wäre ich gekommen.",
