    private fun esattoChunk5(): Map<String, String> = mapOf(
            "Nel discorso indiretto si riferisce ciò che ha detto qualcun altro senza virgolette; spesso si usa il Konjunktiv I per prendere le distanze dalla notizia." to "In indirect speech you report what someone else said without quotation marks; Konjunktiv I is often used to distance oneself from the information.",
            "Nel discorso indiretto si riferisce ci� che ha detto qualcun altro senza virgolette; spesso si usa il Konjunktiv I per prendere le distanze dalla notizia." to "In indirect speech you report what someone else said without quotation marks; Konjunktiv I is often used to distance oneself from the information.",
            "Konjunktiv I di sein è sei, di haben è habe, di werden è werde, di können è könne, di müssen è müsse." to "Konjunktiv I of sein is sei, of haben is habe, of werden is werde, of können is könne, of müssen is müsse.",
            "Konjunktiv I di sein � sei, di haben � habe, di werden � werde, di k�nnen � k�nne, di m�ssen � m�sse." to "Konjunktiv I of sein is sei, of haben is habe, of werden is werde, of können is könne, of müssen is müsse.",
            "Per i verbi regolari il Konjunktiv I si forma con la radice + -e: er komme, sie gehe, sie habe." to "For regular verbs Konjunktiv I is formed with the stem + -e: er komme, sie gehe, sie habe.",
            "Le forme di ich e du spesso coincidono con l'indicativo; in questi casi si usa il Konjunktiv II per evitare ambiguità: Ich sagte, ich hätte keine Zeit." to "The forms of ich and du often coincide with the indicative; in these cases Konjunktiv II is used to avoid ambiguity: Ich sagte, ich hätte keine Zeit.",
            "Le forme di ich e du spesso coincidono con l'indicativo; in questi casi si usa il Konjunktiv II per evitare ambiguit�: Ich sagte, ich h�tte keine Zeit." to "The forms of ich and du often coincide with the indicative; in these cases Konjunktiv II is used to avoid ambiguity: Ich sagte, ich hätte keine Zeit.",
            "Le domande indirette usano ob per le domande sì/no e il W-Wort per le domande con W-Wort; il verbo va alla fine. Gli ordini si riportano con sollen o mögen." to "Indirect questions use ob for yes/no questions and the W-word for W-questions; the verb goes to the end. Commands are reported with sollen or mögen.",
            "Le domande indirette usano ob per le domande s�/no e il W-Wort per le domande con W-Wort; il verbo va alla fine. Gli ordini si riportano con sollen o m�gen." to "Indirect questions use ob for yes/no questions and the W-word for W-questions; the verb goes to the end. Commands are reported with sollen or mögen.",
            "Le forme di wir e sie spesso coincidono con l'indicativo; per chiarezza si può usare il Konjunktiv II." to "The forms of wir and sie often coincide with the indicative; for clarity Konjunktiv II can be used.",
            "Le forme di wir e sie spesso coincidono con l'indicativo; per chiarezza si pu� usare il Konjunktiv II." to "The forms of wir and sie often coincide with the indicative; for clarity Konjunktiv II can be used.",
