            "Nel discorso indiretto formale si usa il Konjunktiv I: sei." to "In formal indirect speech Konjunktiv I is used: sei.",
            "Dopo ob il verbo va alla fine: ... ob ich komme." to "After ob the verb goes to the end: ... ob ich komme.",
            "La frase con dass è possibile, ma il discorso indiretto richiede spesso il Konjunktiv I." to "A clause with dass is possible, but indirect speech often requires Konjunktiv I.",
            "La frase con dass � possibile, ma il discorso indiretto richiede spesso il Konjunktiv I." to "A clause with dass is possible, but indirect speech often requires Konjunktiv I.",
            "Discorso indiretto: Konjunktiv I. Domande: ob/W-Wort + verbo alla fine." to "Indirect speech: Konjunktiv I. Questions: ob/W-word + verb at the end.",
            "Konjunktiv I di sein: er sei." to "Konjunktiv I of sein: er sei.",
            "Konjunktiv I di haben: sie habe." to "Konjunktiv I of haben: sie habe.",
            "Poiché müssen al Konjunktiv I coincide con l'indicativo, si usa il Konjunktiv II müssten." to "Since müssen in Konjunktiv I coincides with the indicative, Konjunktiv II müssten is used.",
            "Poich� m�ssen al Konjunktiv I coincide con l'indicativo, si usa il Konjunktiv II m�ssten." to "Since müssen in Konjunktiv I coincides with the indicative, Konjunktiv II müssten is used.",
            "La domanda indiretta sì/no si introduce con ob." to "An indirect yes/no question is introduced with ob.",
