            "Dopo il W-Wort il verbo va alla fine: ... wo ich wohne." to "After the W-word the verb goes to the end: ... wo ich wohne.",
            "Konjunktiv I di sein alla terza persona: sei." to "Konjunktiv I of sein in the third person: sei.",
            "Konjunktiv I di haben alla terza persona: habe." to "Konjunktiv I of haben in the third person: habe.",
            "Konjunktiv I di sollen: ich solle." to "Konjunktiv I of sollen: ich solle.",
