            "Trasforma in discorso indiretto: Er sagt: �Ich bin krank.�" to "Change to indirect speech: Er sagt: \"Ich bin krank.\"",
            "La frase diventa una subordinata senza dass; il verbo è al Konjunktiv I: sei." to "The sentence becomes a subordinate clause without dass; the verb is in Konjunktiv I: sei.",
            "La frase diventa una subordinata senza dass; il verbo � al Konjunktiv I: sei." to "The sentence becomes a subordinate clause without dass; the verb is in Konjunktiv I: sei.",
