            "In tedesco molti verbi e aggettivi diventano nomi; i nomi si scrivono sempre con la maiuscola." to "In German many verbs and adjectives become nouns; nouns are always capitalised.",
            "L'infinito sostantivato è sempre neutro: das Essen, das Lernen, das Lesen, das Schlafen." to "The nominalised infinitive is always neuter: das Essen, das Lernen, das Lesen, das Schlafen.",
            "L'infinito sostantivato � sempre neutro: das Essen, das Lernen, das Lesen, das Schlafen." to "The nominalised infinitive is always neuter: das Essen, das Lernen, das Lesen, das Schlafen.",
            "I suffissi più comuni sono -ung (die Prüfung), -heit (die Freiheit), -keit (die Möglichkeit), -schaft (die Freundschaft), -nis (das Ergebnis), -tum (das Wachstum)." to "The most common suffixes are -ung (die Prüfung), -heit (die Freiheit), -keit (die Möglichkeit), -schaft (die Freundschaft), -nis (das Ergebnis), -tum (das Wachstum).",
            "I suffissi pi� comuni sono -ung (die Pr�fung), -heit (die Freiheit), -keit (die M�glichkeit), -schaft (die Freundschaft), -nis (das Ergebnis), -tum (das Wachstum)." to "The most common suffixes are -ung (die Prüfung), -heit (die Freiheit), -keit (die Möglichkeit), -schaft (die Freundschaft), -nis (das Ergebnis), -tum (das Wachstum).",
            "Le preposizioni si combinano spesso con i nomi: beim Lernen, zum Essen, nach dem Essen, vor dem Schlafen." to "Prepositions are often combined with nouns: beim Lernen, zum Essen, nach dem Essen, vor dem Schlafen.",
            "Lo stile nominale è tipico della lingua scritta e formale; nel parlato si preferisce spesso la frase verbale." to "Nominal style is typical of written and formal language; in speech the verbal phrase is often preferred.",
            "Lo stile nominale � tipico della lingua scritta e formale; nel parlato si preferisce spesso la frase verbale." to "Nominal style is typical of written and formal language; in speech the verbal phrase is often preferred.",
