    private fun esattoChunk6(): Map<String, String> = mapOf(
            "Nel passivo con modale la frase ha **due infiniti in fondo**: il modale coniugato in seconda posizione e `Partizip II + werden` alla fine." to "In the passive with a modal, the sentence has **two infinitives at the end**: the conjugated modal in second position and `Partizip II + werden` at the end.",
            "Schema: **Subjekt + Modalverb + ... + Partizip II + werden**. Es: Der Antrag muss ausgefüllt werden." to "Pattern: **Subject + modal verb + ... + Partizip II + werden**. E.g.: Der Antrag muss ausgefüllt werden.",
            "Il soggetto della frase passiva è ciò che subisce l'azione; l'agente, se espresso, va con **von + dativo**." to "The subject of the passive sentence is what undergoes the action; the agent, if expressed, takes **von + dative**.",
            "Con i modali il passivo si usa molto nel linguaggio amministrativo e sanitario: Die Tabletten müssen zweimal täglich genommen werden." to "With modals the passive is widely used in administrative and medical language: Die Tabletten müssen zweimal täglich genommen werden.",
            "Al passato: **modalverb al Präteritum + Partizip II + werden**: Das Formular musste ausgefüllt werden." to "In the past: **modal verb in Präteritum + Partizip II + werden**: Das Formular musste ausgefüllt werden.",
            "Con **nicht** la negazione sta prima di Partizip II + werden: Das darf nicht gemacht werden." to "With **nicht** the negation comes before Partizip II + werden: Das darf nicht gemacht werden.",
            "Attenzione all'ordine: il modale NON va in fondo e `werden` resta all'infinito." to "Pay attention to word order: the modal does NOT go to the end and `werden` stays in the infinitive.",
            "Il modulo deve essere compilato." to "The form must be filled out.",
            "I pazienti devono essere visitati regolarmente." to "Patients must be examined regularly.",
            "Qui non è permesso fumare." to "Smoking is not permitted here.",
            "L'appuntamento purtroppo non ha potuto essere spostato." to "Unfortunately the appointment could not be rescheduled.",
            "La fattura deve essere pagata entro venerdì." to "The invoice must be paid by Friday.",
            "Dopo il modale il passivo resta all'infinito: werden, non wird." to "After the modal the passive remains in the infinitive: werden, not wird.",
            "Partizip II prima di werden, entrambi in fondo." to "Partizip II before werden, both at the end.",
            "nicht precede il blocco Partizip II + werden." to "nicht precedes the block Partizip II + werden.",
            "Modale + ... + Partizip II + werden. Due infiniti in fondo, modale in seconda posizione." to "Modal + ... + Partizip II + werden. Two infinitives at the end, modal in second position.",
            "Soggetto neutro singolare (das Formular): muss." to "Neuter singular subject (das Formular): muss.",
            "Al passivo serve il Partizip II: genommen." to "In the passive the Partizip II is needed: genommen.",
            "Soggetto impersonale-es: hier darf nicht geraucht werden." to "Impersonal subject: hier darf nicht geraucht werden.",
            "Al passato il modale va al Präteritum: konnte." to "In the past the modal goes to Präteritum: konnte.",
            "Partizip II di bezahlen: bezahlt, senza ge-." to "Partizip II of bezahlen: bezahlt, without ge-.",
            "Partizip II di untersuchen: untersucht, senza ge-." to "Partizip II of untersuchen: untersucht, without ge-.",
            "Man muss das Formular ausfüllen. (passivo con modale)" to "Man muss das Formular ausfüllen. (passive with modal)",
            "Il complemento oggetto diventa soggetto: Der Antrag muss ausgefüllt werden." to "The direct object becomes the subject: Der Antrag muss ausgefüllt werden.",
            "Traduci: I documenti devono essere firmati." to "Translate: The documents must be signed.",
            "müssen + unterschrieben + werden." to "müssen + unterschrieben + werden.",
            "Il Konjunktiv II passato si forma con **hätte/wäre + Partizip II**: Ich hätte mehr gelernt." to "Konjunktiv II past is formed with **hätte/wäre + Partizip II**: Ich hätte mehr gelernt.",
            "Usa **hätte** con la maggior parte dei verbi; usa **wäre** con i verbi di movimento e cambiamento di stato (gehen, fahren, kommen, bleiben, werden)." to "Use **hätte** with most verbs; use **wäre** with verbs of movement and change of state (gehen, fahren, kommen, bleiben, werden).",
            "Esprime un'ipotesi **irreale nel passato** o un rimpianto: Wenn ich Zeit gehabt hätte, wäre ich gekommen." to "It expresses an **unreal hypothesis in the past** or a regret: Wenn ich Zeit gehabt hätte, wäre ich gekommen.",
            "Nel periodo ipotetico il verbo della subordinata va in fondo: Wenn ich das gewusst hätte, ..." to "In conditional sentences the verb of the subordinate clause goes to the end: Wenn ich das gewusst hätte, ...",
            "La proposizione principale può iniziare con il verbo: Hätte ich das gewusst, wäre ich geblieben." to "The main clause can start with the verb: Hätte ich das gewusst, wäre ich geblieben.",
            "I modali al Konjunktiv II passato usano l'infinito: Ich hätte das machen können." to "Modals in Konjunktiv II past use the infinitive: Ich hätte das machen können.",
            "Non si usa il Konjunktiv II passato per fatti reali: per il passato reale si usa il Perfekt." to "Konjunktiv II past is not used for real facts: for real past events use Perfekt.",
            "Se l'avessi saputo, sarei rimasto." to "If I had known, I would have stayed.",
            "Avrei dovuto studiare di più." to "I should have studied more.",
            "Saremmo partiti prima, ma ha piovuto." to "We would have left earlier, but it rained.",
            "Se avessi avuto tempo, ti avrei aiutato." to "If I had had time, I would have helped you.",
            "Le sarebbe piaciuto diventare medico." to "She would have liked to become a doctor.",
            "L'ipotesi irreale vuole il Konjunktiv II: hätte gewusst." to "The unreal hypothesis requires Konjunktiv II: hätte gewusst.",
            "fahren esprime movimento: ausiliare wäre." to "fahren expresses movement: auxiliary wäre.",
            "Con i modali resta l'infinito: können." to "With modals the infinitive remains: können.",
            "hätte/wäre + Partizip II. Movimento → wäre. Modali → infinito in fondo." to "hätte/wäre + Partizip II. Movement → wäre. Modals → infinitive at the end.",
            "Subordinata con verbo in fondo: gehabt hätte." to "Subordinate clause with verb at the end: gehabt hätte.",
            "fahren è movimento: wir wären gefahren." to "fahren is movement: wir wären gefahren.",
            "lernen usa haben: ich hätte lernen sollen." to "lernen uses haben: ich hätte lernen sollen.",
            "werden esprime cambiamento di stato: wäre geworden." to "werden expresses change of state: wäre geworden.",
            "Konjunktiv II di haben alla terza persona singolare: hätte." to "Konjunktiv II of haben, third person singular: hätte.",
            "helfen usa haben: ich hätte geholfen." to "helfen uses haben: ich hätte geholfen.",
            "Ich habe das nicht gewusst. (Konjunktiv II passato)" to "Ich habe das nicht gewusst. (Konjunktiv II past)",
            "Trasforma il fatto reale in ipotesi: hätte gewusst." to "Transform the real fact into a hypothesis: hätte gewusst.",
            "Traduci: Se avessi tempo, verrei." to "Translate: If I had time, I would come.",
            "Ipotesi irreale nel presente: hätte + würde + infinito." to "Unreal hypothesis in the present: hätte + würde + infinitive.",
            "Una frase relativa può essere compressa in un **participio attributivo**: Die Ware, die gestern bestellt wurde → Die gestern bestellte Ware." to "A relative clause can be compressed into an **attributive participle**: Die Ware, die gestern bestellt wurde → Die gestern bestellte Ware.",
            "Il participio si comporta come un aggettivo e prende la **desinenza** dell'articolo che lo precede." to "The participle behaves like an adjective and takes the **ending** of the article that precedes it.",
            "Participio presente (**Partizip I**): infinito + d, con valore attivo: der schlafende Patient (il paziente che dorme)." to "Present participle (**Partizip I**): infinitive + d, with active meaning: der schlafende Patient (the sleeping patient).",
            "Participio passato (**Partizip II**) con valore passivo: die bestellte Ware (la merce che è stata ordinata)." to "Past participle (**Partizip II**) with passive meaning: die bestellte Ware (the ordered goods).",
            "Le informazioni aggiuntive stanno **prima** del participio: die gestern vom Arzt untersuchte Patientin." to "Additional information comes **before** the participle: die gestern vom Arzt untersuchte Patientin.",
            "Con i verbi separabili il participio resta unito: die eingekaufte Ware." to "With separable verbs the participle stays together: die eingekaufte Ware.",
            "Le costruzioni participiali sono tipiche dello stile scritto e giornalistico; nel parlato si preferisce la relativa." to "Participial constructions are typical of written and journalistic style; in speech the relative clause is preferred.",
            "La merce ordinata ieri arriva domani." to "The goods ordered yesterday arrive tomorrow.",
            "Il paziente che dorme non deve essere disturbato." to "The sleeping patient must not be disturbed.",
            "Il modulo compilato dalla dottoressa è sul tavolo." to "The form filled out by the doctor is on the table.",
            "I medicinali acquistati sono costosi." to "The purchased medicines are expensive.",
            "Il paziente da operare è pronto." to "The patient to be operated on is ready.",
            "La relativa si comprime in participio attributivo." to "The relative clause is compressed into an attributive participle.",
            "Il participio attributivo prende la desinenza dell'aggettivo." to "The attributive participle takes the adjective ending.",
            "Participio presente + desinenza: schlafende." to "Present participle + ending: schlafende.",
            "Relativa → participio + desinenza davanti al nome. Partizip I = attivo, Partizip II = passivo." to "Relative clause → participle + ending before the noun. Partizip I = active, Partizip II = passive.",
            "Femminile singolare con articolo definito: bestellte." to "Feminine singular with definite article: bestellte.",
            "Maschile singolare nominativo con articolo definito: schlafende." to "Masculine singular nominative with definite article: schlafende.",
            "Neutro singolare nominativo: ausgefüllte." to "Neuter singular nominative: ausgefüllte.",
            "Plurale con articolo definito: eingekauften." to "Plural with definite article: eingekauften.",
            "Participio presente + desinenza: arbeitende." to "Present participle + ending: arbeitende.",
            "Participio passato + desinenza: ausgefüllte." to "Past participle + ending: ausgefüllte.",
            "La relativa diventa: die gestern gekommene Rechnung." to "The relative clause becomes: die gestern gekommene Rechnung.",
            "Traduci: I pazienti visitati ieri stanno bene." to "Translate: The patients examined yesterday are well.",
            "Participio attributivo plurale: die gestern untersuchten Patienten." to "Plural attributive participle: die gestern untersuchten Patienten.",
            "Molti verbi tedeschi reggono una **preposizione fissa** che non si traduce parola per parola: warten **auf** + accusativo, helfen **bei** + dativo." to "Many German verbs take a **fixed preposition** that doesn't translate word for word: warten **auf** + accusative, helfen **bei** + dative.",
            "La preposizione può essere **accusativa** (warten auf, sich freuen auf, denken an, sich interessieren für) o **dativa** (helfen bei, sich beschäftigen mit, danken für + accusativo)." to "The preposition can be **accusative** (warten auf, sich freuen auf, denken an, sich interessieren für) or **dative** (helfen bei, sich beschäftigen mit, danken für + accusative).",
            "Con le persone si usano spesso i **pronomi preposizionali**: darauf, daran, damit, davon, womit, worauf." to "With people, **prepositional pronouns** are often used: darauf, daran, damit, davon, womit, worauf.",
            "Per cose si usa **da-/wo- + preposizione**: Ich warte darauf. Worauf wartest du?" to "For things use **da-/wo- + preposition**: Ich warte darauf. Worauf wartest du?",
            "Per persone si usa **preposizione + pronome**: Ich warte auf dich. Ich denke an sie." to "For people use **preposition + pronoun**: Ich warte auf dich. Ich denke an sie.",
            "Alcune coppie frequenti: sich freuen **auf** (attesa) / sich freuen **über** (cosa già avvenuta), denken **an**, sprechen **über** / **von**, sich erinnern **an**." to "Some common pairs: sich freuen **auf** (anticipation) / sich freuen **über** (something that has happened), denken **an**, sprechen **über** / **von**, sich erinnern **an**.",
            "Altre coppie frequenti: sich bewerben **um** + accusativo, abhängen **von** + dativo (separabile: hängt ... ab)." to "Other common pairs: sich bewerben **um** + accusative, abhängen **von** + dative (separable: hängt ... ab).",
            "La preposizione non cambia con il tempo verbale: Ich habe auf dich gewartet." to "The preposition does not change with tense: Ich habe auf dich gewartet.",
            "Verbi e preposizioni frequenti" to "Common verbs and prepositions",
            "Cosa" to "Thing",
            "Domanda" to "Question",
            "Risposta" to "Answer",
            "Aspetto il medico." to "I'm waiting for the doctor.",
            "Non vede l'ora che arrivi il fine settimana." to "She's looking forward to the weekend.",
            "Si interessa di fisioterapia." to "He's interested in physiotherapy.",
            "Ti ringrazio per l'aiuto." to "Thank you for the help.",
            "Cosa aspetti? — Aspetto l'autobus." to "What are you waiting for? — I'm waiting for the bus.",
            "Pensi spesso alla tua famiglia?" to "Do you often think about your family?",
            "warten regge auf + accusativo, non für." to "warten takes auf + accusative, not für.",
            "sich interessieren regge für + accusativo." to "sich interessieren takes für + accusative.",
            "Per le cose si usa il pronome preposizionale: darauf." to "For things use the prepositional pronoun: darauf.",
            "Ogni verbo ha la sua preposizione. Cose → da-/wo- + preposizione; persone → preposizione + pronome." to "Every verb has its preposition. Things → da-/wo- + preposition; people → preposition + pronoun.",
            "warten auf + accusativo." to "warten auf + accusative.",
            "sich interessieren für + accusativo." to "sich interessieren für + accusative.",
            "helfen bei + dativo." to "helfen bei + dative.",
            "denken an + accusativo." to "denken an + accusative.",
            "Per una cosa si usa darauf." to "For a thing use darauf.",
            "danken für + accusativo." to "danken für + accusative.",
            "Ich freue mich auf den Urlaub. (domanda con worauf)" to "Ich freue mich auf den Urlaub. (question with worauf)",
            "La preposizione si unisce a wo-: worauf." to "The preposition combines with wo-: worauf.",
            "Traduci: Aspetto una risposta." to "Translate: I'm waiting for an answer.",
            "warten auf + accusativo: auf eine Antwort." to "warten auf + accusative: auf eine Antwort.",
            "**was** si usa dopo i pronomi indefiniti (alles, etwas, nichts, vieles), dopo i superlativi (das Beste) e dopo un'intera frase: Das ist alles, was ich weiß." to "**was** is used after indefinite pronouns (alles, etwas, nichts, vieles), after superlatives (das Beste) and after a whole sentence: Das ist alles, was ich weiß.",
            "**wo** sostituisce un complemento di luogo: Die Stadt, wo ich lebe. È comune nel parlato; nello scritto si preferisce in der ich lebe." to "**wo** replaces a place complement: Die Stadt, wo ich lebe. Common in speech; in writing in der ich lebe is preferred.",
            "**wer** introduce una relativa senza antecedente con valore di 'chi': Wer viel lernt, versteht mehr." to "**wer** introduces a relative clause without antecedent meaning 'whoever': Wer viel lernt, versteht mehr.",
            "**wo** può anche sostituire espressioni temporali: In dem Moment, wo er kam." to "**wo** can also replace temporal expressions: In dem Moment, wo er kam.",
            "Dopo **was** il verbo va in fondo alla frase, come in ogni relativa." to "After **was** the verb goes to the end of the clause, as in every relative clause.",
            "Se il pronome relativo è soggetto, il verbo concorda: Die Leute, die hier arbeiten." to "If the relative pronoun is the subject, the verb agrees: Die Leute, die hier arbeiten.",
            "Non si usa **was** dopo un nome concreto: *Das Buch, was ich lese* è sbagliato → Das Buch, das ich lese." to "**was** is not used after a concrete noun: *Das Buch, was ich lese* is wrong → Das Buch, das ich lese.",
            "Quale pronome relativo?" to "Which relative pronoun?",
            "Antecedente" to "Antecedent",
            "Pronome" to "Pronoun",
            "È tutto quello che so a riguardo." to "That's everything I know about it.",
            "La città dove sono cresciuto è piccola." to "The city where I grew up is small.",
            "Chi si esercita con impegno migliora." to "Whoever practises diligently improves.",
            "Ha superato l'esame, cosa che rallegra tutti." to "He passed the exam, which makes everyone happy.",
            "L'unica cosa che mi manca è il tempo." to "The only thing I'm missing is time.",
            "Dopo un nome concreto si usa der/die/das, non was." to "After a concrete noun use der/die/das, not was.",
            "Dopo alles si usa was." to "After alles use was.",
            "La relativa con wer ha il verbo in fondo; la principale resta in seconda posizione." to "The relative clause with wer has the verb at the end; the main clause stays in second position.",
            "was dopo alles/etwas/nichts e frasi intere; wo per il luogo; wer per 'chi' senza antecedente." to "was after alles/etwas/nichts and whole sentences; wo for places; wer for 'whoever' without antecedent.",
            "Nome concreto neutro: das." to "Concrete neuter noun: das.",
            "Complemento di luogo: wo." to "Place complement: wo.",
            "Relativa senza antecedente con valore di 'chi': wer." to "Relative clause without antecedent meaning 'whoever': wer.",
            "Dopo das Einzige si usa was." to "After das Einzige use was.",
            "La relativa che riprende un'intera frase usa was." to "A relative clause referring to a whole sentence uses was.",
            "Ich wohne in einer Stadt. Die Stadt ist groß. (relativa con wo)" to "Ich wohne in einer Stadt. Die Stadt ist groß. (relative clause with wo)",
            "Unisci con wo: Die Stadt, wo ich wohne, ist groß." to "Combine with wo: Die Stadt, wo ich wohne, ist groß.",
            "Traduci: Chi lavora molto, ha poco tempo." to "Translate: Whoever works a lot has little time.",
            "Relativa con wer: Wer viel arbeitet, ..." to "Relative clause with wer: Wer viel arbeitet, ...",
            "Lo stile nominale sostituisce un verbo con un **nome**: entscheiden → die Entscheidung, lesen → das Lesen." to "Nominal style replaces a verb with a **noun**: entscheiden → die Entscheidung, lesen → das Lesen.",
            "I nomi in **-ung** derivano da verbi e sono femminili: die Verbesserung, die Behandlung, die Entscheidung." to "Nouns in **-ung** derive from verbs and are feminine: die Verbesserung, die Behandlung, die Entscheidung.",
            "L'infinito sostantivato è neutro: **das Lesen**, **das Sprechen**, **das Warten**." to "The nominalised infinitive is neuter: **das Lesen**, **das Sprechen**, **das Warten**.",
            "I nomi in **-heit/-keit** derivano da aggettivi e sono femminili: die Gesundheit, die Möglichkeit." to "Nouns in **-heit/-keit** derive from adjectives and are feminine: die Gesundheit, die Möglichkeit.",
            "Nello stile nominale le preposizioni sostituiscono le congiunzioni: **wegen** (perché), **trotz** (benché), **während** (mentre), **nach** (dopo)." to "In nominal style prepositions replace conjunctions: **wegen** (because), **trotz** (although), **während** (while), **nach** (after).",
            "Le espressioni nominali rendono il testo più formale e compatto, tipico di lettere, referti e testi B2." to "Nominal expressions make text more formal and compact, typical of letters, reports and B2 texts.",
            "Non abusare dello stile nominale nel parlato: suona rigido. Usalo nello scritto formale." to "Don't overuse nominal style in speech: it sounds stiff. Use it in formal writing.",
            "Verbale" to "Verbal",
            "Nominale" to "Nominal",
            "Il trattamento del paziente dura due settimane." to "The patient's treatment lasts two weeks.",
            "A causa della sua malattia non ha potuto venire." to "Because of his illness he could not come.",
            "Nonostante la pioggia andiamo a passeggio." to "Despite the rain we go for a walk.",
            "La lettura aiuta nell'apprendimento." to "Reading helps with learning.",
            "Il miglioramento della qualità è necessario." to "Improving quality is necessary.",
            "Da behandeln deriva il nome femminile die Behandlung." to "From behandeln comes the feminine noun die Behandlung.",
            "wegen regge il genitivo: des Regens." to "wegen takes the genitive: des Regens.",
            "I nomi in -heit sono femminili: die Gesundheit." to "Nouns in -heit are feminine: die Gesundheit.",
            "Verbo → nome (-ung femminile, infinito neutro). Congiunzione → preposizione (wegen, trotz, während, nach)." to "Verb → noun (-ung feminine, neuter infinitive). Conjunction → preposition (wegen, trotz, während, nach).",
            "Da behandeln deriva die Behandlung." to "From behandeln comes die Behandlung.",
            "La preposizione che sostituisce 'weil' è wegen + genitivo." to "The preposition replacing 'weil' is wegen + genitive.",
            "trotz = nonostante: trotz des Regens." to "trotz = despite: trotz des Regens.",
            "L'infinito sostantivato è neutro e maiuscolo: das Lesen." to "The nominalised infinitive is neuter and capitalised: das Lesen.",
            "Suffisso -ung, genere femminile: die Entscheidung." to "Suffix -ung, feminine gender: die Entscheidung.",
            "Suffisso -heit, genere femminile: die Gesundheit." to "Suffix -heit, feminine gender: die Gesundheit.",
            "Weil er krank ist, bleibt er zu Hause. (stile nominale)" to "Weil er krank ist, bleibt er zu Hause. (nominal style)",
            "weil + frase → wegen + genitivo: wegen seiner Krankheit." to "weil + clause → wegen + genitive: wegen seiner Krankheit.",
            "Traduci: Il miglioramento della qualità è importante." to "Translate: Improving quality is important.",
            "Verbesserung + genitivo: die Verbesserung der Qualität." to "Verbesserung + genitive: die Verbesserung der Qualität.",

