    private fun esattoChunk7(): Map<String, String> = mapOf(
            "I possessivi hanno una radice (mein-, dein-, sein-, ihr-, unser-, euer-, ihr-, Ihr-) e una desinenza." to "Possessives have a stem (mein-, dein-, sein-, ihr-, unser-, euer-, ihr-, Ihr-) and an ending.",
            "Al nominativo maschile e neutro non hanno desinenza: mein Vater, mein Kind. Femminile e plurale prendono -e: meine Mutter, meine Eltern." to "In the masculine and neuter nominative they have no ending: mein Vater, mein Kind. Feminine and plural take -e: meine Mutter, meine Eltern.",
            "All'accusativo cambia solo il maschile: meinen Vater. Femminile, neutro e plurale restano uguali: meine Mutter, mein Kind, meine Eltern." to "In the accusative only the masculine changes: meinen Vater. Feminine, neuter and plural stay the same: meine Mutter, mein Kind, meine Eltern.",
            "euer perde la e interna quando prende la desinenza: euer Vater, ma eure Mutter, euren Vater." to "euer drops the inner e when taking an ending: euer Vater, but eure Mutter, euren Vater.",
            "kein si declina come ein: kein Vater, keine Mutter, kein Kind, keine Eltern; all'accusativo maschile keinen Vater." to "kein declines like ein: kein Vater, keine Mutter, kein Kind, keine Eltern; in the masculine accusative keinen Vater.",
            "Usa kein davanti a un nome senza articolo o con articolo indeterminativo. Usa nicht per negare verbi, aggettivi e nomi propri: Ich arbeite nicht. Er ist nicht müde." to "Use kein before a noun without article or with an indefinite article. Use nicht to negate verbs, adjectives and proper nouns: Ich arbeite nicht. Er ist nicht müde.",
            "All'accusativo maschile aggiungi -en: meinen Vater, deinen Bruder." to "In the masculine accusative add -en: meinen Vater, deinen Bruder.",
            "Nome neutro senza articolo" to "Neuter noun without article",
            "Nome femminile senza articolo" to "Feminine noun without article",
            "Nome maschile all'accusativo" to "Masculine noun in the accusative",
            "Verbo, aggettivo o nome proprio" to "Verb, adjective or proper noun",
            "Mio padre lavora a Bressanone." to "My father works in Brixen.",
            "Questa è mia sorella." to "This is my sister.",
            "Vedo mio fratello." to "I see my brother.",
            "Amiamo i nostri genitori." to "We love our parents.",
            "Non ho tempo." to "I don't have time.",
            "Zeit è un nome femminile senza articolo: si nega con keine." to "Zeit is a feminine noun without article: negate it with keine.",
            "Mutter è femminile: il possessivo prende -e, meine." to "Mutter is feminine: the possessive takes -e, meine.",
            "Bruder è maschile all'accusativo: mein + -en = meinen." to "Bruder is masculine in the accusative: mein + -en = meinen.",
            "mein Vater, meine Mutter, mein Kind, meine Eltern. Accusativo maschile: meinen Vater. Negazione del nome: kein/keine/keinen." to "mein Vater, meine Mutter, mein Kind, meine Eltern. Masculine accusative: meinen Vater. Negating nouns: kein/keine/keinen.",
            "Vater è maschile singolare al nominativo: mein Vater." to "Vater is masculine singular nominative: mein Vater.",
            "Schwester è femminile: seine Schwester." to "Schwester is feminine: seine Schwester.",
            "Bruder è maschile all'accusativo: meinen Bruder." to "Bruder is masculine accusative: meinen Bruder.",
            "Eltern è plurale: unsere Eltern." to "Eltern is plural: unsere Eltern.",
            "Hund è maschile all'accusativo: deinen Hund." to "Hund is masculine accusative: deinen Hund.",
            "Buch è neutro al nominativo: dein Buch." to "Buch is neuter nominative: dein Buch.",
            "Kinder è plurale: unsere Kinder. A inizio frase: Unsere." to "Kinder is plural: unsere Kinder. At the start of a sentence: Unsere.",
            "Zeit è femminile senza articolo: keine Zeit." to "Zeit is feminine without article: keine Zeit.",
            "Lehrer è maschile singolare: kein Lehrer." to "Lehrer is masculine singular: kein Lehrer.",
            "Problem è neutro: kein Problem." to "Problem is neuter: kein Problem.",
            "Questa è la mia borsa." to "This is my bag.",
            "borsa = Tasche, femminile: meine Tasche." to "bag = Tasche, feminine: meine Tasche.",
            "Mio fratello non ha tempo." to "My brother has no time.",
            "Mein Bruder (nominativo) + keine Zeit (negazione del nome)." to "Mein Bruder (nominative) + keine Zeit (negating the noun).",
            "Le preposizioni miste sono nove: an, auf, in, über, unter, vor, hinter, neben, zwischen." to "The two-way prepositions are nine: an, auf, in, über, unter, vor, hinter, neben, zwischen.",
            "Rispondono a Wo? (dove?) con il dativo quando indicano posizione: Ich bin in der Schule." to "They answer Wo? (where?) with the dative when indicating position: Ich bin in der Schule.",
            "Rispondono a Wohin? (dove vai?) con l'accusativo quando indicano movimento o direzione: Ich gehe in die Schule." to "They answer Wohin? (where to?) with the accusative when indicating movement or direction: Ich gehe in die Schule.",
            "Alcuni verbi aiutano: liegen, stehen, sitzen, hängen (stato) vogliono il dativo; legen, stellen, setzen, hängen (movimento) vogliono l'accusativo." to "Some verbs help: liegen, stehen, sitzen, hängen (state) take the dative; legen, stellen, setzen, hängen (movement) take the accusative.",
            "Contrazioni frequenti: in + das = ins, an + das = ans, in + dem = im, an + dem = am, bei + dem = beim." to "Common contractions: in + das = ins, an + das = ans, in + dem = im, an + dem = am, bei + dem = beim.",
            "Attenzione: il dativo plurale aggiunge -n: in den Häusern, mit den Kindern." to "Note: the dative plural adds -n: in den Häusern, mit den Kindern.",
            "Sono a scuola." to "I'm at school.",
            "Vado a scuola." to "I'm going to school.",
            "Il libro è sul tavolo." to "The book is on the table.",
            "Metto il libro sul tavolo." to "I put the book on the table.",
            "Il gatto è sotto il divano." to "The cat is under the sofa.",
            "Posizione (Wo?) vuole il dativo: in der Schule." to "Position (Wo?) requires the dative: in der Schule.",
            "Movimento (Wohin?) vuole l'accusativo: in die Schule." to "Movement (Wohin?) requires the accusative: in die Schule.",
            "legen indica movimento: auf den Tisch." to "legen indicates movement: auf den Tisch.",
            "Wo? -> dativo. Wohin? -> accusativo. liegen/stehen/sitzen = dativo; legen/stellen/setzen = accusativo." to "Wo? -> dative. Wohin? -> accusative. liegen/stehen/sitzen = dative; legen/stellen/setzen = accusative.",
            "Movimento verso il parco (maschile): in den Park." to "Movement towards the park (masculine): in den Park.",
            "Posizione sul tavolo: auf dem Tisch (dativo)." to "Position on the table: auf dem Tisch (dative).",
            "stellen indica movimento: in den Kühlschrank (accusativo)." to "stellen indicates movement: in den Kühlschrank (accusative).",
            "Con i nomi di città non serve l'articolo: in Berlin." to "With city names no article is needed: in Berlin.",
            "Posizione: auf dem Sofa (dativo)." to "Position: auf dem Sofa (dative).",
            "Movimento verso la parete: an die Wand (accusativo femminile)." to "Movement towards the wall: an die Wand (feminine accusative).",
            "legen indica movimento: in die Tasche." to "legen indicates movement: in die Tasche.",
            "Posizione accanto alla chiesa: neben der Kirche (dativo femminile)." to "Position next to the church: neben der Kirche (feminine dative).",
            "Movimento verso il parco: in den Park (accusativo maschile)." to "Movement towards the park: in den Park (masculine accusative).",
            "Da posizione a movimento: im Haus -> ins Haus." to "From position to movement: im Haus -> ins Haus.",
            "Posizione: liegen + auf dem Tisch (dativo)." to "Position: liegen + auf dem Tisch (dative).",
            "Posizione nel giardino: in dem Garten = im Garten." to "Position in the garden: in dem Garten = im Garten.",

