    private fun esattoChunk8(): Map<String, String> = mapOf(
            "Il comparativo si forma con aggettivo + -er + als: schnell -> schneller als, alt -> älter als." to "The comparative is formed with adjective + -er + als: schnell -> schneller als, alt -> älter als.",
            "Il comparativo si forma con aggettivo + -er + als: schnell -> schneller als, alt -> �lter als." to "The comparative is formed with adjective + -er + als: schnell -> schneller als, alt -> älter als.",
            "Il superlativo si forma con am + aggettivo + -sten, oppure con l'articolo definito + aggettivo + -ste: am schnellsten, der schnellste Zug." to "The superlative is formed with am + adjective + -sten, or with the definite article + adjective + -ste: am schnellsten, der schnellste Zug.",
            "Molti aggettivi brevi prendono l'umlaut: alt -> älter, jung -> jünger, groß -> größer, kalt -> kälter, warm -> wärmer, stark -> stärker, lang -> länger." to "Many short adjectives take an umlaut: alt -> älter, jung -> jünger, groß -> größer, kalt -> kälter, warm -> wärmer, stark -> stärker, lang -> länger.",
            "Molti aggettivi brevi prendono l'umlaut: alt -> �lter, jung -> j�nger, gro� -> gr��er, kalt -> k�lter, warm -> w�rmer, stark -> st�rker, lang -> l�nger." to "Many short adjectives take an umlaut: alt -> älter, jung -> jünger, groß -> größer, kalt -> kälter, warm -> wärmer, stark -> stärker, lang -> länger.",
            "Forme irregolari: gut -> besser -> am besten; viel -> mehr -> am meisten; gern -> lieber -> am liebsten; hoch -> höher -> am höchsten; nah -> näher -> am nächsten." to "Irregular forms: gut -> besser -> am besten; viel -> mehr -> am meisten; gern -> lieber -> am liebsten; hoch -> höher -> am höchsten; nah -> näher -> am nächsten.",
            "Forme irregolari: gut -> besser -> am besten; viel -> mehr -> am meisten; gern -> lieber -> am liebsten; hoch -> h�her -> am h�chsten; nah -> n�her -> am n�chsten." to "Irregular forms: gut -> besser -> am besten; viel -> mehr -> am meisten; gern -> lieber -> am liebsten; hoch -> höher -> am höchsten; nah -> näher -> am nächsten.",
            "Per indicare uguaglianza si usa so + aggettivo + wie: Er ist so groß wie sein Vater." to "To indicate equality use so + adjective + wie: Er ist so groß wie sein Vater.",
            "Per indicare uguaglianza si usa so + aggettivo + wie: Er ist so gro� wie sein Vater." to "To indicate equality use so + adjective + wie: Er ist so groß wie sein Vater.",
            "Non usare wie con il comparativo: besser als, non besser wie." to "Don't use wie with the comparative: besser als, not besser wie.",
