            "viel � irregolare: mehr, non vieler." to "viel is irregular: mehr, not vieler.",
            "Comparativo: -er + als. Superlativo: am -sten / der -ste. Uguaglianza: so ... wie." to "Comparative: -er + als. Superlative: am -sten / der -ste. Equality: so ... wie.",
            "Il Futur I si forma con werden + infinito in fondo alla frase: Ich werde morgen lernen." to "Futur I is formed with werden + infinitive at the end: Ich werde morgen lernen.",
            "Coniugazione di werden: ich werde, du wirst, er/sie/es wird, wir werden, ihr werdet, sie/Sie werden." to "Conjugation of werden: ich werde, du wirst, er/sie/es wird, wir werden, ihr werdet, sie/Sie werden.",
            "Il futuro si usa per piani, previsioni e promesse. Spesso il presente con un'espressione di tempo è più naturale: Morgen lerne ich Deutsch." to "The future is used for plans, predictions and promises. Often the present with a time expression is more natural: Morgen lerne ich Deutsch.",
            "Il futuro si usa per piani, previsioni e promesse. Spesso il presente con un'espressione di tempo � pi� naturale: Morgen lerne ich Deutsch." to "The future is used for plans, predictions and promises. Often the present with a time expression is more natural: Morgen lerne ich Deutsch.",
            "Molti verbi reggono l'infinito con zu: versuchen, vergessen, vorhaben, hoffen, planen, anfangen, aufhören, beschließen." to "Many verbs take the infinitive with zu: versuchen, vergessen, vorhaben, hoffen, planen, anfangen, aufhören, beschließen.",
            "Molti verbi reggono l'infinito con zu: versuchen, vergessen, vorhaben, hoffen, planen, anfangen, aufh�ren, beschlie�en." to "Many verbs take the infinitive with zu: versuchen, vergessen, vorhaben, hoffen, planen, anfangen, aufhören, beschließen.",
            "Con i verbi separabili, zu entra tra prefisso e verbo: anzurufen, aufzustehen, einzukaufen." to "With separable verbs, zu comes between prefix and verb: anzurufen, aufzustehen, einzukaufen.",
            "I verbi modali e lassen vogliono l'infinito senza zu: Ich muss lernen. Ich lasse das Auto reparieren." to "Modal verbs and lassen take the infinitive without zu: Ich muss lernen. Ich lasse das Auto reparieren.",
            "Domani andrò a Bolzano." to "Tomorrow I'll go to Bolzano.",
            "Domani andr� a Bolzano." to "Tomorrow I'll go to Bolzano.",
            "Visiteremo i nostri genitori." to "We will visit our parents.",
