            "Con werden l'infinito va in fondo: Deutsch lernen." to "With werden the infinitive goes to the end: Deutsch lernen.",
            "I verbi modali vogliono l'infinito senza zu." to "Modal verbs take the infinitive without zu.",
            "Con i verbi separabili zu entra tra prefisso e verbo: an + zu + rufen." to "With separable verbs zu comes between prefix and verb: an + zu + rufen.",
            "Futur I: werden + infinito in fondo. Infinito con zu: versuchen/vergessen/vorhaben + zu + infinito." to "Futur I: werden + infinitive at the end. Infinitive with zu: versuchen/vergessen/vorhaben + zu + infinitive.",
            "entweder ... oder = o ... o: Entweder komme ich heute oder am Freitag." to "entweder ... oder = either ... or: Entweder komme ich heute oder am Freitag.",
            "weder ... noch = né ... né: Ich habe weder Zeit noch Geld." to "weder ... noch = neither ... nor: Ich habe weder Zeit noch Geld.",
            "weder ... noch = n� ... n�: Ich habe weder Zeit noch Geld." to "weder ... noch = neither ... nor: Ich habe weder Zeit noch Geld.",
