            "je ... desto/umso = quanto pi� ... tanto pi�: Je mehr ich lerne, desto besser verstehe ich." to "je ... desto/umso = the more ... the more: Je mehr ich lerne, desto besser verstehe ich.",
            "zwar ... aber = certo ... ma: Er ist zwar jung, aber sehr erfahren." to "zwar ... aber = admittedly ... but: Er ist zwar jung, aber sehr erfahren.",
            "Con je ... desto il verbo della frase con je va in fondo; nella frase con desto il verbo resta al secondo posto." to "With je ... desto the verb in the je-clause goes to the end; in the desto-clause the verb stays in second position.",
