            "Il Partizip I si forma con l'infinito + d: lachen -> lachend, laufen -> laufend. Esprime un'azione contemporanea e attiva." to "Partizip I is formed with infinitive + d: lachen -> lachend, laufen -> laufend. It expresses a simultaneous, active action.",
            "Il Partizip II dei verbi regolari è ge- + radice + -t: machen -> gemacht. Nei verbi forti è spesso ge-...-en: lesen -> gelesen." to "Partizip II of regular verbs is ge- + stem + -t: machen -> gemacht. In strong verbs it is often ge-...-en: lesen -> gelesen.",
            "Il Partizip II dei verbi regolari � ge- + radice + -t: machen -> gemacht. Nei verbi forti � spesso ge-...-en: lesen -> gelesen." to "Partizip II of regular verbs is ge- + stem + -t: machen -> gemacht. In strong verbs it is often ge-...-en: lesen -> gelesen.",
            "Come aggettivo, il participio prende la desinenza dell'aggettivo: der lachende Mann, das gelesene Buch, die geöffnete Tür." to "As an adjective, the participle takes the adjective ending: der lachende Mann, das gelesene Buch, die geöffnete Tür.",
            "Come aggettivo, il participio prende la desinenza dell'aggettivo: der lachende Mann, das gelesene Buch, die ge�ffnete T�r." to "As an adjective, the participle takes the adjective ending: der lachende Mann, das gelesene Buch, die geöffnete Tür.",
            "Il Partizip I come aggettivo è attivo: der lachende Mann = l'uomo che ride." to "Partizip I as an adjective is active: der lachende Mann = the man who is laughing.",
            "Il Partizip I come aggettivo � attivo: der lachende Mann = l'uomo che ride." to "Partizip I as an adjective is active: der lachende Mann = the man who is laughing.",
