            "Il Partizip II come aggettivo ha spesso valore passivo o di risultato: das gelesene Buch = il libro che � stato letto." to "Partizip II as an adjective often has a passive or result meaning: das gelesene Buch = the book that has been read.",
            "Le frasi participiali possono essere ampliate: die in Berlin lebenden Studenten = gli studenti che vivono a Berlino." to "Participial phrases can be expanded: die in Berlin lebenden Studenten = the students who live in Berlin.",
