    private fun esattoChunk9(): Map<String, String> = mapOf(
            "La desinenza dell'aggettivo dipende da tre fattori: genere/numero del sostantivo, caso, e tipo di articolo che lo precede." to "The adjective ending depends on three factors: gender/number of the noun, case, and the type of article before it.",
            "Dopo articolo determinativo (der/die/das) l'aggettivo è 'debole': desinenza -e (nom/akk plurale) o -en (tutti gli altri casi)." to "After a definite article (der/die/das) the adjective is 'weak': ending -e (nom/acc plural) or -en (all other cases).",
            "Dopo articolo indeterminativo (ein/eine) o kein/possessivi l'aggettivo è 'forte' dove l'articolo non porta la marca del caso: nominativo maschile -er, neutro -es, accusativo maschile -en; negli altri casi -e/-en." to "After an indefinite article (ein/eine) or kein/possessives the adjective is 'strong' where the article lacks the case marker: masculine nominative -er, neuter -es, masculine accusative -en; in other cases -e/-en.",
            "Senza articolo (aggettivo nudo) l'aggettivo è 'forte': maschile/neutro nominativo -er/-es, tutti gli altri casi -en." to "Without an article the adjective is 'strong': masculine/neuter nominative -er/-es, all other cases -en.",
            "La regola d'oro: l'articolo 'forte' rende l'aggettivo 'debole' e viceversa; se manca l'articolo, l'aggettivo fa tutto il lavoro." to "Golden rule: a 'strong' article makes the adjective 'weak' and vice versa; if the article is missing, the adjective does all the work.",
            "Senza articolo l'aggettivo porta la marca del caso da solo." to "Without an article the adjective carries the case marker on its own.",
            "Il cagnolino gioca in giardino." to "The little dog plays in the garden.",
            "Vedo un cagnolino." to "I see a little dog.",
            "È un bambino piccolo." to "He's a little child.",
            "Passeggiare con il cagnolino." to "Walking with the little dog.",
            "Caffè fresco e latte fresco." to "Fresh coffee and fresh milk.",
            "I cagnolini sono spesso rumorosi." to "Little dogs are often noisy.",
            "Dopo articolo determinativo l'aggettivo è debole: -e." to "After a definite article the adjective is weak: -e.",
            "Accusativo maschile: articolo einen + aggettivo -en." to "Masculine accusative: article einen + adjective -en.",
            "Dativo: aggettivo -en anche dopo articolo determinativo." to "Dative: adjective -en even after a definite article.",
            "Articolo forte = aggettivo debole (-e/-en). Articolo debole = aggettivo forte (-er/-es/-en). Nessun articolo = aggettivo forte." to "Strong article = weak adjective (-e/-en). Weak article = strong adjective (-er/-es/-en). No article = strong adjective.",
            "Il Konjunktiv II esprime desideri irrealizzabili, richieste cortesi e possibilità ipotetiche." to "Konjunktiv II expresses unfulfillable wishes, polite requests and hypothetical possibilities.",
            "Forma più comune: würde + Infinitiv (per la maggior parte dei verbi): Ich würde gern kommen." to "Most common form: würde + infinitive (for most verbs): Ich würde gern kommen.",
            "Per sein, haben, können, müssen, sollen, dürfen, wissen si usano le forme proprie: wäre, hätte, könnte, müsste, sollte, dürfte, wüsste." to "For sein, haben, können, müssen, sollen, dürfen, wissen use their own forms: wäre, hätte, könnte, müsste, sollte, dürfte, wüsste.",
            "Richiesta cortese: Ich hätte gern einen Kaffee. / Könnten Sie das Fenster öffnen? / Würden Sie bitte...?" to "Polite request: Ich hätte gern einen Kaffee. / Könnten Sie das Fenster öffnen? / Würden Sie bitte...?",
            "Desiderio irrealizzabile: Wenn ich reich wäre, würde ich ein Haus kaufen. (se fossi ricco, comprerei una casa)" to "Unfulfillable wish: Wenn ich reich wäre, würde ich ein Haus kaufen. (if I were rich, I would buy a house)",
            "La forma würde + Infinitiv è sempre corretta; le forme proprie sono più eleganti per sein/haben/können/müssen." to "The form würde + infinitive is always correct; the special forms are more elegant for sein/haben/können/müssen.",
            "Vorrei un caffè." to "I'd like a coffee.",
            "Potrebbe aiutarmi, per favore?" to "Could you help me, please?",
            "Se fossi ricco, viaggerei per il mondo." to "If I were rich, I would travel the world.",
            "Dovresti bere più acqua." to "You should drink more water.",
            "Vorrei andare in Italia." to "I'd like to go to Italy.",
            "Per 'vorrei' si usa hätte, non würde haben." to "For 'I would like' use hätte, not würde haben.",
            "Se fossi ricco: wäre, non würde." to "If I were rich: wäre, not würde.",
            "Richiesta cortese: Konjunktiv II könnte, non indicativo." to "Polite request: Konjunktiv II könnte, not indicative.",
            "würde + Infinitiv per i verbi normali; hätte/wäre/könnte/müsste per sein/haben/können/müssen." to "würde + infinitive for regular verbs; hätte/wäre/könnte/müsste for sein/haben/können/müssen.",
            "Alcuni verbi tedeschi richiedono una preposizione fissa, con un caso fisso (accusativo o dativo) che non dipende dalla posizione nel tedesco." to "Some German verbs require a fixed preposition with a fixed case (accusative or dative) that does not depend on position.",
            "La preposizione si impara insieme al verbo come un blocco: warten auf (+Akk), denken an (+Akk), sich interessieren für (+Akk)." to "The preposition is learned together with the verb as a block: warten auf (+acc), denken an (+acc), sich interessieren für (+acc).",
            "Il caso è fisso: anche se la preposizione è di luogo, non si applica la regola wo/wohin." to "The case is fixed: even if the preposition is locative, the wo/wohin rule does not apply.",
            "warten richiede auf, non für." to "warten requires auf, not für.",
            "denken richiede an, non über." to "denken requires an, not über.",
            "sich interessieren richiede für, non an." to "sich interessieren requires für, not an.",
            "Il verbo sceglie la preposizione e il caso: imparali insieme come un blocco unico." to "The verb chooses the preposition and case: learn them together as a single block.",
            "man = soggetto impersonale (si): Man sagt das so. (si dice così). man è sempre nominativo singolare." to "man = impersonal subject (one): Man sagt das so. man is always nominative singular.",
            "jemand = qualcuno, niemand = nessuno. Si declinano come aggettivi senza articolo." to "jemand = someone, niemand = no one. They decline like adjectives without an article.",
            "etwas = qualcosa, nichts = niente. Sono invariabili (non si declinano)." to "etwas = something, nichts = nothing. They are invariable (not declined).",
            "alle = tutti, alcune = alcuni, mehrere = parecchi, manche = alcuni (non tutti). Si declinano come aggettivi senza articolo." to "alle = everyone/all, einige = some, mehrere = several, manche = some (not all). They decline like adjectives without an article.",
            "Indefiniti con articolo: ein paar (alcuni), ein bisschen/ein wenig (un po')." to "Indefinites with article: ein paar (a few), ein bisschen/ein wenig (a little).",
            "Qui non si può parcheggiare." to "Parking is not allowed here.",
            "Ha telefonato qualcuno." to "Someone called.",
            "Non ho capito niente." to "I didn't understand anything.",
            "Sono venuti tutti." to "Everyone came.",
            "Ho visto qualcuno." to "I saw someone.",
            "Ci sono alcuni studenti." to "There are a few students.",
            "La domanda indiretta riferisce una domanda senza punto interrogativo; il verbo coniugato va alla fine della frase indiretta." to "An indirect question reports a question without a question mark; the conjugated verb goes to the end of the indirect clause.",
            "Domanda sì/no indiretta: ob + verbo alla fine. (Ich weiß nicht, ob er kommt.)" to "Indirect yes/no question: ob + verb at the end. (Ich weiß nicht, ob er kommt.)",
            "Domanda con W-Wort indiretta: W-Wort + verbo alla fine. (Ich frage, wann er kommt.)" to "Indirect W-question: W-word + verb at the end. (Ich frage, wann er kommt.)",
            "Il punto interrogativo si mette solo se la frase principale è una domanda: Weißt du, ob er kommt?" to "A question mark is used only if the main clause is a question: Weißt du, ob er kommt?",
            "Non so se viene." to "I don't know if he's coming.",
            "Chiedo quando vieni." to "I'm asking when you're coming.",
            "Vorrei sapere quanto costa." to "I'd like to know how much it costs.",
            "Sai se ha tempo?" to "Do you know if he has time?",
            "I Fragewörter (pronomi/avverbi interrogativi) introducono domande aperte: wer (chi), was (cosa), wo (dove), wann (quando), warum (perché), wie (come), wohin (dove, direzione), woher (da dove)." to "Question words (interrogative pronouns/adverbs) introduce open questions: wer (who), was (what), wo (where), wann (when), warum (why), wie (how), wohin (where to), woher (where from).",
            "Nelle domande con Fragewort il verbo coniugato va in seconda posizione (dopo il Fragewort): Wo arbeitest du?" to "In questions with a question word the conjugated verb goes in second position (after the question word): Wo arbeitest du?",
            "welcher/welche/welches (quale) si declina come l'articolo determinativo." to "welcher/welche/welches (which) declines like the definite article.",
            "wie + aggettivo/avverbio: Wie alt bist du? Wie viel kostet das? Wie oft gehst du?" to "wie + adjective/adverb: Wie alt bist du? Wie viel kostet das? Wie oft gehst du?",
            "was für (ein) = che tipo di: Was für ein Auto hast du?" to "was für (ein) = what kind of: Was für ein Auto hast du?",
            "Chi sei?" to "Who are you?",
            "Cosa fai?" to "What do you do?",
            "Dove lavori?" to "Where do you work?",
            "Quando vieni?" to "When are you coming?",
            "Quanti anni hai?" to "How old are you?",
            "Quale libro leggi?" to "Which book are you reading?",
            "Il verbo va in seconda posizione: Wo arbeitest du?" to "The verb goes in second position: Wo arbeitest du?",
            "Fragewort in prima posizione, verbo coniugato in seconda. welcher/welche/welches si declina come l'articolo." to "Question word in first position, conjugated verb in second. welcher/welche/welches declines like the article.",

            "controverso" to "controversial",
            "indiscusso" to "undisputed",
            "evidente" to "evident/obvious",
