    private fun esattoChunk11(): Map<String, String> = mapOf(
            "Il Plusquamperfekt esprime un'azione conclusa prima di un'altra azione passata: Als ich ankam, war er schon gegangen." to "The pluperfect expresses an action completed before another past action: Als ich ankam, war er schon gegangen.",
            "Forma: ausiliare al Präteritum (hatte/war) + Partizip II — come il Perfekt, ma con hatte/war invece di hat/ist." to "Form: auxiliary in Präteritum (hatte/war) + Partizip II — like Perfekt, but with hatte/war instead of hat/ist.",
            "Ausiliare (come nel Perfekt): haben per la maggior parte dei verbi, sein per i verbi di movimento/cambiamento di stato." to "Auxiliary (as in Perfekt): haben for most verbs, sein for verbs of movement/change of state.",
            "Con nachdem la frase con il Plusquamperfekt va prima: Nachdem er gegessen hatte, ging er." to "With nachdem the clause with pluperfect comes first: Nachdem er gegessen hatte, ging er.",
            "Con als il Plusquamperfekt esprime l'anteriorità rispetto all'azione principale." to "With als the pluperfect expresses anteriority relative to the main action.",
            "L'ausiliare del Plusquamperfekt è sempre al Präteritum (hatte/war)." to "The pluperfect auxiliary is always in Präteritum (hatte/war).",
            "Quando arrivai, era già partito." to "When I arrived, he had already left.",
            "Dopo che se ne era andata, feci ordine." to "After she had left, I tidied up.",
            "Avevo già letto il libro quando me ne parlasti." to "I had already read the book when you told me about it.",
            "Era già partito quando arrivammo." to "He had already left when we arrived.",
            "Azione precedente in contesto passato: Plusquamperfekt (war ... gegangen)." to "Previous action in a past context: pluperfect (war ... gegangen).",
            "Dopo nachdem il verbo va al Plusquamperfekt." to "After nachdem the verb goes to pluperfect.",
            "Verbi di movimento: ausiliare sein (war)." to "Verbs of movement: auxiliary sein (war).",
            "Plusquamperfekt = hatte/war (Präteritum) + Partizip II; l'azione precedente prende il Plusquamperfekt." to "Pluperfect = hatte/war (Präteritum) + Partizip II; the earlier action takes the pluperfect.",
            "Alcuni sostantivi maschili (per lo più persone, professioni, nazionalità) prendono -n o -en in tutti i casi tranne il nominativo singolare." to "Some masculine nouns (mostly people, professions, nationalities) take -n or -en in all cases except nominative singular.",
            "Genitivo singolare: -n (der Studenten) oppure -ens (des Herrn)." to "Genitive singular: -n (der Studenten) or -ens (des Herrn).",
            "Plurale: forma regolare + -n se non termina già in -n." to "Plural: regular form + -n if it doesn't already end in -n.",
            "La desinenza si aggiunge al nominativo singolare: Student → Studenten (akk/dat/gen), Herr → Herrn (akk/dat) / Herrn(s) (gen)." to "The ending is added to the nominative singular: Student → Studenten (acc/dat/gen), Herr → Herrn (acc/dat) / Herrn(s) (gen).",
            "Con preposizioni come mit, bei, zu il dativo resta: mit dem Kollegen." to "With prepositions like mit, bei, zu the dative remains: mit dem Kollegen.",
            "Il genitivo di Herr è des Herrn (con -n + -s)." to "The genitive of Herr is des Herrn (with -n + -s).",
            "Lo studente viene." to "The student is coming.",
            "Vedo lo studente." to "I see the student.",
            "Aiuto lo studente." to "I help the student.",
            "Il libro dello studente è nuovo." to "The student's book is new.",
            "Il collega che conosco è simpatico." to "The colleague I know is nice.",
            "n-Deklination: accusativo -en." to "n-declension: accusative -en.",
            "Dativo: -en." to "Dative: -en.",
            "Genitivo: -en." to "Genitive: -en.",
            "Maschile persona/professione → -n/-en in tutti i casi tranne il nominativo singolare." to "Masculine person/profession → -n/-en in all cases except nominative singular.",
            "Alcune preposizioni reggono il genitivo: wegen (a causa di), trotz (nonostante), während (durante), (an)statt (invece di), außerhalb (fuori di), innerhalb (dentro), oberhalb (sopra), unterhalb (sotto)." to "Some prepositions take the genitive: wegen (because of), trotz (despite), während (during), (an)statt (instead of), außerhalb (outside), innerhalb (inside), oberhalb (above), unterhalb (below).",
            "wegen esprime la causa: Wegen des Wetters bleibe ich zu Hause." to "wegen expresses cause: Wegen des Wetters bleibe ich zu Hause.",
            "trotz esprime la concessione (nonostante): Trotz der Kälte gehen wir spazieren." to "trotz expresses concession (despite): Trotz der Kälte gehen wir spazieren.",
            "während esprime il tempo (durante): Während des Films schlief er ein." to "während expresses time (during): Während des Films schlief er ein.",
            "anstatt/statt esprime la sostituzione: Anstatt zu arbeiten, spielte er." to "anstatt/statt expresses substitution: Anstatt zu arbeiten, spielte er.",
            "Eccezione: con i pronomi personali queste preposizioni reggono il dativo: wegen mir, trotz dir, währenddessen." to "Exception: with personal pronouns these prepositions take the dative: wegen mir, trotz dir, währenddessen.",
            "A causa del tempo resto a casa." to "Because of the weather I stay home.",
            "Nonostante il freddo usciamo a passeggiare." to "Despite the cold we go for a walk.",
            "Durante il film si addormentò." to "During the film he fell asleep.",
            "Invece di lavorare, giocò." to "Instead of working, he played.",
            "Fuori città è tranquillo." to "Outside the city it's quiet.",
            "wegen + genitivo: des Wetters." to "wegen + genitive: des Wetters.",
            "trotz + genitivo: der Kälte." to "trotz + genitive: der Kälte.",
            "wegen/trotz/während/anstatt + genitivo del sostantivo; con pronomi personali → dativo." to "wegen/trotz/während/anstatt + genitive of the noun; with personal pronouns → dative.",
            "Un aggettivo può diventare sostantivo: prende la maiuscola e si declina come aggettivo (forte/debole/mista)." to "An adjective can become a noun: it is capitalised and declined like an adjective (strong/weak/mixed).",
            "Molto frequenti con persone: der Angestellte (l'impiegato), der Beamte (il funzionario), der Deutsche (il tedesco), der Verwandte (il parente), der Bekannte (il conoscente), der Verletzte (il ferito)." to "Very common with people: der Angestellte (employee), der Beamte (civil servant), der Deutsche (German person), der Verwandte (relative), der Bekannte (acquaintance), der Verletzte (injured person).",
            "La declinazione segue le regole dell'aggettivo: dopo articolo determinativo desinenza -e/-en, dopo indeterminativo -er/-es/-en, senza articolo -er/-es/-en." to "Declension follows adjective rules: after definite article endings -e/-en, after indefinite -er/-es/-en, without article -er/-es/-en.",
            "Il vecchio aspetta all'angolo." to "The old man waits at the corner.",
            "Aiuto il vecchio." to "I help the old man.",
            "I malati vengono curati." to "The sick are being treated.",
            "La cosa bella del viaggio è il tempo." to "The beautiful thing about the trip is the weather.",
            "L'impiegato lavora in ufficio." to "The employee works in the office.",
            "Aggettivo sostantivato = maiuscola + declinazione aggettivale (come dopo articolo)." to "Nominalised adjective = capital letter + adjective declension (as after an article).",
            "Il pronome avverbiale (Präpositionaladverb) = da(r)-/wo(r)- + preposizione: dafür, darauf, damit, worüber, wofür, woran." to "The pronominal adverb (Präpositionaladverb) = da(r)-/wo(r)- + preposition: dafür, darauf, damit, worüber, wofür, woran.",
            "da- + preposizione per le affermazioni: Ich denke daran. (= Ich denke an das Problem.)" to "da- + preposition for statements: Ich denke daran. (= Ich denke an das Problem.)",
            "wo- + preposizione per le domande: Worauf wartest du? (= Auf was wartest du?)" to "wo- + preposition for questions: Worauf wartest du? (= Auf was wartest du?)",
            "Se la preposizione inizia con vocale, si usa dar-/wor-: darauf, worauf, daran, woran." to "If the preposition starts with a vowel, use dar-/wor-: darauf, worauf, daran, woran.",
            "Sostituiscono 'preposizione + es/esso': Ich denke an das Problem → Ich denke daran." to "They replace 'preposition + es/it': Ich denke an das Problem → Ich denke daran.",
            "Si riferiscono a una cosa o a un'intera frase precedente, evitando ripetizioni." to "They refer to a thing or a whole preceding sentence, avoiding repetition.",
            "Penso al problema. → Ci penso." to "I think about the problem. → I think about it.",
            "Parla del libro. → Ne parla." to "He's talking about the book. → He's talking about it.",
            "Cosa aspetti? — L'autobus." to "What are you waiting for? — The bus.",
            "Di cosa parla? — Del libro." to "What is she talking about? — About the book.",
            "Con preposizione + es si usa il pronome avverbiale: daran." to "With preposition + es use the pronominal adverb: daran.",
            "In tedesco standard si usa worüber, non 'über was'." to "In standard German use worüber, not 'über was'.",
            "da(r)- per le affermazioni, wo(r)- per le domande; sostituiscono 'preposizione + es'." to "da(r)- for statements, wo(r)- for questions; they replace 'preposition + es'.",
            "je ... desto/umso: proporzionalità (più ... più): Je mehr ich lerne, desto besser verstehe ich." to "je ... desto/umso: proportionality (the more ... the more): Je mehr ich lerne, desto besser verstehe ich.",
            "In entrambe le frasi il verbo coniugato va alla fine." to "In both clauses the conjugated verb goes to the end.",
            "als ob / als wenn: come se (ipotesi irrealizzabile): Er tut, als ob er nichts wüsste. → Konjunktiv II nell'ultima frase." to "als ob / als wenn: as if (unreal hypothesis): Er tut, als ob er nichts wüsste. → Konjunktiv II in the last clause.",
            "als (con comparativo): confronto: Er ist größer, als ich dachte." to "als (with comparative): comparison: Er ist größer, als ich dachte.",
            "wie (con comparativo): uguaglianza: Er ist so groß wie ich." to "wie (with comparative): equality: Er ist so groß wie ich.",
            "je nachdem: a seconda di: Je nachdem, wie viel Zeit wir haben, gehen wir ins Kino." to "je nachdem: depending on: Je nachdem, wie viel Zeit wir haben, gehen wir ins Kino.",
            "Più mi esercito, più scorrevole parlo." to "The more I practise, the more fluently I speak.",
            "Fa come se fosse malato." to "He acts as if he were ill.",
            "È più grande di quanto pensassi." to "He's taller than I thought.",
            "È tanto intelligente quanto sua sorella." to "She's as intelligent as her sister.",
            "A seconda di come è tardi, andiamo al cinema." to "Depending on how late it is, we go to the cinema.",
            "je ... desto: verbo alla fine in entrambe le frasi; als ob → Konjunktiv II." to "je ... desto: verb at the end in both clauses; als ob → Konjunktiv II.",

