            "Verbi tipici: sagen (dire), zeigen (mostrare), erklären (spiegare), schicken (mandare), wünschen (augurare), geben (dare), bringen (portare), empfehlen (raccomandare), erzählen (raccontare), versprechen (promettere)." to "Typical verbs: sagen (to say), zeigen (to show), erklären (to explain), schicken (to send), wünschen (to wish), geben (to give), bringen (to bring), empfehlen (to recommend), erzählen (to tell), versprechen (to promise).",
