            "«Mentre cucino, ascolto la radio.»" to "\"While I cook, I listen to the radio.\"",
            "während = mentre; nella subordinata il verbo va in fondo." to "während = while; in the subordinate clause the verb goes to the end.",

            "Il tedesco usa forme sostitutive del passivo per evitare il passivo vero e proprio." to "German uses substitute passive forms to avoid the true passive.",
            "sich lassen + Infinitiv: esprime possibilità. Die Tür lässt sich öffnen. (= Die Tür kann geöffnet werden.)" to "sich lassen + infinitive: expresses possibility. Die Tür lässt sich öffnen. (= Die Tür kann geöffnet werden.)",
            "sein + zu + Infinitiv: esprime necessità o possibilità. Das ist zu machen. (= Das muss/kann gemacht werden.)" to "sein + zu + infinitive: expresses necessity or possibility. Das ist zu machen. (= Das muss/kann gemacht werden.)",
            "man + verbo attivo: Man kann das machen." to "man + active verb: Man kann das machen.",
            "Passivo con modale (già trattato): Das muss gemacht werden." to "Passive with modal (already covered): Das muss gemacht werden.",
            "sich lassen = può essere fatto; sein + zu = deve/può essere fatto." to "sich lassen = can be done; sein + zu = must/can be done.",
            "La porta si apre facilmente." to "The door opens easily.",
            "Il problema è difficile da risolvere." to "The problem is hard to solve.",
            "Questo non si può fare." to "This cannot be done.",
            "Il testo si legge bene." to "The text reads well.",
            "Vorgangspassiv (azione in corso): werden + Partizip II. Die Tür wird geöffnet. (la porta viene aperta)" to "Action passive (ongoing action): werden + Partizip II. Die Tür wird geöffnet. (the door is being opened)",
            "Zustandspassiv (stato risultante): sein + Partizip II. Die Tür ist geöffnet. (la porta è aperta — stato)" to "Stative passive (resulting state): sein + Partizip II. Die Tür ist geöffnet. (the door is open — state)",
            "Il Zustandspassiv descrive lo stato che resta dopo l'azione, spesso con aggettivi di stato." to "The stative passive describes the state remaining after the action, often with stative adjectives.",
            "Si usa per descrivere condizioni, risultati, stati: Die Tür ist geschlossen. Das Auto ist repariert." to "It is used to describe conditions, results, states: Die Tür ist geschlossen. Das Auto ist repariert.",
            "Attenzione: sein + Partizip II può anche essere un aggettivo (Die geschlossene Tür = la porta chiusa)." to "Note: sein + Partizip II can also be an adjective (Die geschlossene Tür = the closed door).",
            "La porta viene aperta." to "The door is being opened.",
            "La porta è aperta." to "The door is open.",
            "La porta è chiusa." to "The door is closed.",
            "L'auto è riparata." to "The car is repaired.",
            "werden + Partizip II = azione; sein + Partizip II = stato risultante." to "werden + Partizip II = action; sein + Partizip II = resulting state.",
            "Le particelle modali (doch, mal, ja, halt, eben, schon, noch, eigentlich, etwa, wohl, denn) non cambiano il significato letterale ma l'atteggiamento del parlante." to "Modal particles (doch, mal, ja, halt, eben, schon, noch, eigentlich, etwa, wohl, denn) don't change literal meaning but the speaker's attitude.",
            "doch: sorpresa, insistenza, esortazione. Komm doch! (Vieni su!)" to "doch: surprise, insistence, encouragement. Komm doch! (Do come!)",
            "mal: attenuazione, richiesta cortese. Komm mal her! (Vieni un po' qui.)" to "mal: softening, polite request. Komm mal her! (Come here for a moment.)",
            "ja: ovvio, conosciuto. Das ist ja klar! (È ovvio!)" to "ja: obvious, known. Das ist ja klar! (That's obvious!)",
            "halt/eben: rassegnazione. Das ist halt so. (È così, non ci si può fare nulla.)" to "halt/eben: resignation. Das ist halt so. (That's just how it is.)",
            "schon: certezza o dubbio. Das wird schon klappen. (Andrà bene.)" to "schon: reassurance or doubt. Das wird schon klappen. (It'll work out.)",
            "eigentlich: vera domanda. Was machst du eigentlich? (Cosa fai veramente?)" to "eigentlich: genuine question. Was machst du eigentlich? (What are you actually doing?)",
            "denn: curiosità. Was machst du denn? (Cosa fai? — tono curioso)" to "denn: curiosity. Was machst du denn? (What are you doing? — curious tone)",
            "wohl: probabilità. Er wird wohl krank sein. (Sarà probabilmente malato.)" to "wohl: probability. Er wird wohl krank sein. (He's probably ill.)",
            "Vieni su! (insistenza)" to "Do come! (insistence)",
            "Guarda un po'! (attenuazione)" to "Have a look! (softening)",
            "È fantastico! (ovvio)" to "That's great! (obvious)",
            "È così. (rassegnazione)" to "That's just how it is. (resignation)",
            "Cosa fai? (curiosità)" to "What are you doing? (curiosity)",
            "Le particelle modali non si traducono: si sentono. Cambiano il tono, non il contenuto." to "Modal particles aren't translated: they're felt. They change tone, not content.",
            "Nei testi lunghi si usano parole di riferimento per evitare ripetizioni: diese/jene, dabei, dadurch, hierfür, dies, das, es." to "In longer texts reference words are used to avoid repetition: diese/jene, dabei, dadurch, hierfür, dies, das, es.",
            "diese/jene: riferimento a un sostantivo precedente (questo/quello). Die Stadt ist schön. Diese Stadt liegt am Meer." to "diese/jene: reference to a previous noun (this/that). Die Stadt ist schön. Diese Stadt liegt am Meer.",
            "dabei, dadurch, hierfür, dafür: riferimento a un'intera frase o situazione precedente." to "dabei, dadurch, hierfür, dafür: reference to a whole previous sentence or situation.",
            "Le parole di riferimento sono fondamentali per la comprensione dei testi (Goethe B2 Lesen Teil 2)." to "Reference words are essential for text comprehension (Goethe B2 Lesen Teil 2).",
            "derselbe/dieselbe/dasselbe = la stessa cosa/la stessa persona (identità): declinazione come l'articolo determinativo." to "derselbe/dieselbe/dasselbe = the same thing/person (identity): declined like the definite article.",
            "derjenige/diejenige/dasjenige = colui che/colui che... (relativo con antecedente generico)." to "derjenige/diejenige/dasjenige = the one who... (relative with generic antecedent).",
            "La città è bella. Questa città si trova al mare." to "The city is beautiful. This city is by the sea.",
            "Studiò molto. Grazie a ciò superò l'esame." to "He studied a lot. Thanks to that he passed the exam.",
            "Arrivò in ritardo. Questo fu un problema." to "He arrived late. That was a problem.",
            "L'uomo che sta là è il mio capo." to "The man standing there is my boss.",
            "diese/jene → sostantivo; dabei/dadurch/hierfür → frase intera; dies/das/es → frase intera (senza sostantivo)." to "diese/jene → noun; dabei/dadurch/hierfür → whole sentence; dies/das/es → whole sentence (without noun).",
            "Alcuni verbi tedeschi reggono due oggetti: un accusativo (cosa) e un dativo (persona)." to "Some German verbs take two objects: an accusative (thing) and a dative (person).",
            "Ordine tipico: verbo + dativo (persona) + accusativo (cosa): Ich sage dir die Wahrheit." to "Typical order: verb + dative (person) + accusative (thing): Ich sage dir die Wahrheit.",
            "Se l'accusativo è un pronome, viene prima del dativo: Ich sage es dir. (non: Ich sage dir es.)" to "If the accusative is a pronoun, it comes before the dative: Ich sage es dir. (not: Ich sage dir es.)",
            "Se il dativo è un pronome, viene prima dell'accusativo (se l'accusativo è un nome): Ich sage dir die Wahrheit." to "If the dative is a pronoun, it comes before the accusative (if the accusative is a noun): Ich sage dir die Wahrheit.",
            "Ti dico la verità." to "I'm telling you the truth.",
            "Ti mostro il libro." to "I'll show you the book.",
            "Ti mando una lettera." to "I'll send you a letter.",
            "Ti auguro molta fortuna." to "I wish you lots of luck.",
            "Te lo dico." to "I'll tell you that.",
            "Verbi con due oggetti: dativo (persona) + accusativo (cosa); se l'accusativo è un pronome, viene prima." to "Verbs with two objects: dative (person) + accusative (thing); if the accusative is a pronoun, it comes first.",
            "Passivo al Perfekt: sein + Partizip II + worden. Das Haus ist gebaut worden. (la casa è stata costruita)" to "Passive in Perfekt: sein + Partizip II + worden. Das Haus ist gebaut worden. (the house has been built)",
            "Passivo al Präteritum: wurde + Partizip II. Das Haus wurde gebaut. (la casa fu costruita / venne costruita)" to "Passive in Präteritum: wurde + Partizip II. Das Haus wurde gebaut. (the house was built)",
            "Ausiliare del Perfekt passivo: sein (non haben)." to "Auxiliary of passive Perfekt: sein (not haben).",
            "Forma completa del Perfekt passivo: Partizip II + worden (non geworden)." to "Complete form of passive Perfekt: Partizip II + worden (not geworden).",
            "Il Präteritum passivo è più comune nel tedesco scritto/formale; il Perfekt passivo nel parlato." to "Passive Präteritum is more common in written/formal German; passive Perfekt in speech.",
            "La casa fu costruita." to "The house was built.",
            "La casa è stata costruita." to "The house has been built.",
            "La lettera fu scritta." to "The letter was written.",
            "La lettera è stata scritta." to "The letter has been written.",
            "Präteritum passivo: wurde + Partizip II. Perfekt passivo: ist + Partizip II + worden." to "Passive Präteritum: wurde + Partizip II. Passive Perfekt: ist + Partizip II + worden.",
            "Le congiunzioni temporali introducono una subordinata con il verbo alla fine." to "Temporal conjunctions introduce a subordinate clause with the verb at the end.",
            "wenn: per presente, futuro o eventi ripetuti. Wenn ich Zeit habe, gehe ich ins Kino." to "wenn: for present, future or repeated events. Wenn ich Zeit habe, gehe ich ins Kino.",
            "als: per un singolo evento nel passato. Als ich klein war, spielte ich im Garten." to "als: for a single event in the past. Als ich klein war, spielte ich im Garten.",
            "während: mentre (contemporaneità). Während ich arbeite, hört er Musik." to "während: while (simultaneity). Während ich arbeite, hört er Musik.",
            "bevor: prima che. Bevor ich gehe, räume ich auf." to "bevor: before. Bevor ich gehe, räume ich auf.",
            "nachdem: dopo che (l'azione precedente va al Plusquamperfekt). Nachdem er gegessen hatte, ging er." to "nachdem: after (the earlier action takes the pluperfect). Nachdem er gegessen hatte, ging er.",
            "seit/seitdem: da quando. Seitdem er hier wohnt, ist er glücklicher." to "seit/seitdem: since. Seitdem er hier wohnt, ist er glücklicher.",
            "bis: fino a quando. Ich warte, bis er kommt." to "bis: until. Ich warte, bis er kommt.",
            "Se ho tempo, vado al cinema." to "If I have time, I go to the cinema.",
            "Quando ero piccolo, giocavo in giardino." to "When I was little, I played in the garden.",
            "Mentre lavoro, lui ascolta musica." to "While I work, he listens to music.",
            "Prima di andare, faccio ordine." to "Before I go, I tidy up.",
            "Dopo che aveva mangiato, se ne andò." to "After he had eaten, he left.",
            "Da quando abita qui, è più felice." to "Since he has lived here, he is happier.",
            "wenn = presente/futuro/ripetuto; als = singolo evento passato; nachdem + Plusquamperfekt." to "wenn = present/future/repeated; als = single past event; nachdem + pluperfect.",

