            "Parole personalizzate non abilitate per questo profilo" to "Custom words are not enabled for this profile",
            "TUTTI i profili con parole, ripassi, log, test, progressi, conversazioni e correzioni. Il backup va su un repo GitHub privato." to "ALL profiles with words, reviews, logs, tests, progress, conversations and corrections. The backup goes to a private GitHub repo.",
            "Ultimo backup:" to "Last backup:",
            "Salva un file JSON con tutti i profili (parole, ripassi, lezioni, grammatica, conversazioni), le notifiche e il tema. Puoi conservarlo o importarlo su un altro dispositivo." to "Save a JSON file with all profiles (words, reviews, lessons, grammar, conversations), notifications and theme. You can keep it or import it on another device.",
            "Attenzione: il file contiene anche le chiavi API dei profili. Trattalo come un documento riservato. Il token GitHub non è incluso." to "Warning: the file also contains the profiles' API keys. Treat it as a confidential document. The GitHub token is not included.",
            "Formato: utente/nome-repo (es. ItsZale0/tedesco-backup)." to "Format: user/repo-name (e.g. ItsZale0/tedesco-backup).",
            "PASSI:\n1. Crea un repo privato su github.com/new (es. tedesco-backup).\n2. Vai su github.com/settings/personal-access-tokens/new\n3. In \"Repository access\" scegli SOLO il repo di backup.\n4. In \"Permissions\" → Repository permissions → Contents: Read and write.\n5. Genera il token (inizia con github_pat_) e incollalo qui sopra.\nIl token resta solo sul telefono: non viene inviato da nessuna parte tranne a GitHub." to "STEPS:\n1. Create a private repo at github.com/new (e.g. tedesco-backup).\n2. Go to github.com/settings/personal-access-tokens/new\n3. Under \"Repository access\" choose ONLY the backup repo.\n4. Under \"Permissions\" → Repository permissions → Contents: Read and write.\n5. Generate the token (starts with github_pat_) and paste it above.\nThe token stays only on your phone: it is not sent anywhere except to GitHub.",
            "Ultimo automatico:" to "Last automatic backup:",
            "Salva solo quando qualcosa cambia (confronto hash): non consuma richieste GitHub inutilmente." to "Saves only when something changes (hash comparison): it does not waste GitHub requests.",
            "Data:" to "Date:",
            "I progressi vengono UNITI a quelli del telefono: per ogni parola, unità di grammatica e lezione resta la versione più avanzata. Nessuna delle due parti viene cancellata." to "Progress is MERGED with the data on this phone: for each word, grammar unit and lesson the most advanced version is kept. Neither side is deleted.",
            "ATTENZIONE: i dati attuali di questo telefono verranno sovrascritti dal backup. I progressi fatti dopo l'ultimo backup su questo dispositivo andranno persi." to "WARNING: the current data on this phone will be overwritten by the backup. Progress made after the last backup on this device will be lost.",
            "20 minuti al giorno. La grammatica comanda il percorso.\nOgni unità completata è un passo verso la padronanza." to "20 minutes a day. Grammar leads the path.\nEach completed unit is a step towards mastery.",
            "Sblocca completando:" to "Unlock by completing:",
