            "Esercizi di produzione orale: leggi la situazione, parla, registrati e confronta con il modello." to "Speaking exercises: read the situation, speak, record yourself and compare with the model.",
            "Ascolta il modello (anche a 0,7x), ripeti e registrati. Il riconoscimento vocale non basta: l'orecchio va allenato sulle coppie minime." to "Listen to the model (even at 0.7x), repeat and record yourself. Speech recognition is not enough: your ear must be trained on minimal pairs.",
            "A Bressanone e in Austria molte parole quotidiane sono diverse dallo standard. Capirle è parte della competenza reale, non un vezzo. Ogni variante è un arricchimento!" to "In Brixen and Austria many everyday words differ from standard German. Understanding them is part of real competence, not a quirk. Every variant is enriching!",
            "L'immersione fa riconoscere la struttura; la regola spiega perché funziona. Usale insieme: prima la regola, poi il testo." to "Immersion helps you recognise the structure; the rule explains why it works. Use them together: rule first, then the text.",
            "Nessuna produzione scritta valutata. Scrivi un testo in Produzione Scritta e premi Verifica: il tutor lo valuta e il punteggio entra qui." to "No evaluated written production yet. Write a text in Written Production and tap Check: the tutor evaluates it and the score appears here.",
