            "L'alfabeto tedesco ha 26 lettere più ä, ö, ü e la lettera ß (che vale come ss)." to "The German alphabet has 26 letters plus ä, ö, ü and the letter ß (equivalent to ss).",
            "Le combinazioni ei e ie non si leggono allo stesso modo: ei suona [ai], ie suona [i:] lungo." to "The combinations ei and ie are not read the same way: ei sounds [ai], ie sounds long [i:].",
            "sch si pronuncia come la sc di «scena»; z suona [ts]; v spesso suona [f]; w suona [v]." to "sch is pronounced like 'sh' in 'she'; z sounds [ts]; v often sounds [f]; w sounds [v].",
            "La s iniziale davanti a vocale è sonora [z]; sp e st all'inizio di parola suonano [ʃp] e [ʃt]." to "Initial s before a vowel is voiced [z]; sp and st at the beginning of a word sound [ʃp] and [ʃt].",
            "Le vocali con umlaut cambiano suono: ä è più aperta, ö e ü non esistono in italiano e vanno ascoltate e imitate." to "Vowels with umlauts change sound: ä is more open; ö and ü do not exist in English and should be listened to and imitated.",
            "Non serve pronunciare tutto perfettamente: l'importante è non confondere i suoni che cambiano il significato." to "You don't need perfect pronunciation: what matters is not confusing sounds that change meaning.",
            "La durata della vocale aiuta l'orecchio, ma non è necessario misurarla: imita la parola intera." to "Vowel length helps the ear, but you don't need to measure it: imitate the whole word.",
            "Mi chiamo Anna." to "My name is Anna.",
