            "Il verbo heißen si scrive con ß. La ß non è una B: vale come una s sorda." to "The verb heißen is written with ß. ß is not a B: it stands for a voiceless s.",
            "La combinazione ie si legge [i:] lungo; per il suono [ai] si scrive ei, come in mein." to "The combination ie is read as long [i:]; for the sound [ai] you write ei, as in mein.",
            "sch è un unico suono [ʃ], non una s seguita da ch." to "sch is a single sound [ʃ], not an s followed by ch.",
            "ei = ai, ie = i lungo, sch = sc di «scena». La ß vale ss." to "ei = ai, ie = long i, sch = 'sh'. ß equals ss.",
            "Come si pronuncia ei in mein?" to "How is ei pronounced in mein?",
            "ei si pronuncia [ai], come nell'italiano «mai»." to "ei is pronounced [ai], like 'i' in English 'mine'.",
            "Come si pronuncia ie in sie?" to "How is ie pronounced in sie?",
            "ie indica una i lunga: [zi:]." to "ie indicates a long i: [zi:].",
            "Quale parola contiene il suono [ʃ]?" to "Which word contains the sound [ʃ]?",
            "Schule inizia con sch, che si pronuncia [ʃ]." to "Schule begins with sch, which is pronounced [ʃ].",
            "Come si pronuncia la z in Zeit?" to "How is z pronounced in Zeit?",
            "La z tedesca è un'affricata: [ts]." to "German z is an affricate: [ts].",
            "Come si pronuncia la v in Vater?" to "How is v pronounced in Vater?",
            "In molte parole tedesche v suona [f], come in Vater." to "In many German words v sounds [f], as in Vater.",
            "Come si pronuncia la w in Wasser?" to "How is w pronounced in Wasser?",
            "La w tedesca suona [v], come la v italiana in «vino»." to "German w sounds [v], like English v in 'vine'.",
            "Completa: Stra___e (strada)" to "Complete: Stra___e (street)",
            "Si scrive Straße con la ß, che vale come ss." to "It is written Straße with ß, which equals ss.",
            "Scrivi solo la lettera mancante." to "Write only the missing letter.",
            "Come si scrive «scuola» in tedesco?" to "How do you write 'school' in German?",
            "Schule inizia con sch e si scrive con la u finale." to "Schule begins with sch and is written with a final u.",
            "Scrivi solo il sostantivo." to "Write only the noun.",
            "Come si scrive «amico» in tedesco?" to "How do you write 'friend' in German?",
            "Freund è l'amico; l'amica è Freundin." to "Freund is a male friend; a female friend is Freundin.",
            "Scrivi solo il sostantivo maschile." to "Write only the masculine noun.",
            "Scrivi in tedesco: «Mi chiamo Luca.»" to "Write in German: 'My name is Luca.'",
            "Si usa heißen: ich heiße. La ß può essere scritta anche ss in alternativa." to "Use heißen: ich heiße. ß can alternatively be written as ss.",
            "Inizia con Ich." to "Start with Ich.",
            "Come si scrive «ospedale» in tedesco?" to "How do you write 'hospital' in German?",
            "Krankenhaus è un composto: Kranken + Haus, con la h di Haus." to "Krankenhaus is a compound: Kranken + Haus, with the h of Haus.",
            "Scrivi il sostantivo, con l'iniziale maiuscola." to "Write the noun, with a capital initial.",
            "In quale parola la s iniziale è sonora [z]?" to "In which word is the initial s voiced [z]?",
            "Sonne inizia con s davanti a vocale: [z]. Schule e Straße iniziano con [ʃ], Zeit con [ts]." to "Sonne begins with s before a vowel: [z]. Schule and Straße begin with [ʃ], Zeit with [ts].",
            "Scrivi in tedesco: «strada»." to "Write in German: 'street'.",
            "Straße si scrive con sch, a e ß: la ß vale come ss." to "Straße is written with sch, a and ß: ß equals ss.",
            "Una parola sola, con l'iniziale maiuscola." to "One word only, with a capital initial.",
            "I pronomi al nominativo sono: ich, du, er/sie/es, wir, ihr, sie. La forma di cortesia Sie si scrive con la maiuscola." to "Nominative pronouns are: ich, du, er/sie/es, wir, ihr, sie. The polite form Sie is written with a capital letter.",
            "Il verbo sein (essere) è irregolare: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind." to "The verb sein (to be) is irregular: ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind.",
            "Si usa sein per identità, origine, nazionalità, professione, età, stato e luogo: Ich bin Italiener. Sie ist Lehrerin." to "Use sein for identity, origin, nationality, profession, age, state and location: Ich bin Italiener. Sie ist Lehrerin.",
            "Nella frase principale il verbo è in seconda posizione. Nella domanda sì/no il verbo va in prima posizione: Bist du müde?" to "In a main clause the verb is in second position. In a yes/no question the verb goes to first position: Bist du müde?",
            "La forma di cortesia Sie richiede il verbo alla terza persona plurale: Sind Sie Herr Müller?" to "The polite form Sie takes the verb in the third person plural: Sind Sie Herr Müller?",
            "Attenzione: sie (loro) e Sie (cortesia) hanno la stessa forma verbale, ma significati diversi." to "Note: sie (they) and Sie (polite you) share the same verb form but have different meanings.",
            "Il verbo passa dalla seconda alla prima posizione; il resto della frase non cambia." to "The verb moves from second to first position; the rest of the sentence stays the same.",
            "Sono italiano." to "I am Italian.",
            "Di dove sei?" to "Where are you from?",
            "Lei è insegnante." to "She is a teacher.",
            "Siamo felici." to "We are happy.",
            "Lei è il signor Müller?" to "Are you Mr Müller?",
            "L'età si esprime con sein, non con haben: ich bin ... Jahre alt." to "Age is expressed with sein, not haben: ich bin ... Jahre alt.",
            "La terza persona singolare di sein è ist." to "The third person singular of sein is ist.",
            "Se il soggetto è plurale, anche il nome predicativo va al plurale quando possibile." to "If the subject is plural, the predicate noun should also be plural when possible.",
            "sein: bin, bist, ist, sind, seid, sind. L'età si dice con sein." to "sein: bin, bist, ist, sind, seid, sind. Age is expressed with sein.",
            "Ich ___ Student." to "Ich ___ Student.",
            "Con ich si usa bin." to "With ich, use bin.",
            "Du ___ müde." to "Du ___ müde.",
            "Con du si usa bist." to "With du, use bist.",
            "Er ___ aus Berlin." to "Er ___ aus Berlin.",
            "Con er/sie/es si usa ist." to "With er/sie/es, use ist.",
            "Wir ___ Freunde." to "Wir ___ Freunde.",
            "Con wir si usa sind." to "With wir, use sind.",
            "___ ihr aus Italien?" to "___ ihr aus Italien?",
            "Con ihr si usa seid: Seid ihr ...?" to "With ihr, use seid: Seid ihr ...?",
            "Sie (forma di cortesia) ___ Frau Rossi." to "Sie (polite form) ___ Frau Rossi.",
            "La forma di cortesia Sie usa sind, come la terza persona plurale." to "The polite form Sie uses sind, like the third person plural.",
            "Scrivi solo la forma di sein." to "Write only the form of sein.",
            "Ich ___ 30 Jahre alt." to "Ich ___ 30 Jahre alt.",
            "L'età si esprime con sein: ich bin ... Jahre alt." to "Age is expressed with sein: ich bin ... Jahre alt.",
            "Das ___ mein Bruder." to "Das ___ mein Bruder.",
            "Il soggetto das è neutro singolare: ist." to "The subject das is neuter singular: ist.",
            "Trasforma in domanda sì/no: Du bist Lehrer." to "Turn into a yes/no question: Du bist Lehrer.",
            "Bist du Lehrer?" to "Bist du Lehrer?",
            "Il verbo va in prima posizione: Bist du ...?" to "The verb goes to first position: Bist du ...?",
            "Scrivi la domanda completa." to "Write the complete question.",
            "Trasforma in domanda sì/no: Er ist zu Hause." to "Turn into a yes/no question: Er ist zu Hause.",
            "Ist er zu Hause?" to "Ist er zu Hause?",
            "Il verbo ist passa in prima posizione." to "The verb ist moves to first position.",
            "Meine Schwester ___ Ärztin." to "Meine Schwester ___ Ärztin.",
            "Il soggetto è singolare: ist." to "The subject is singular: ist.",
            "Traduci: «Noi siamo stanchi.»" to "Translate: 'We are tired.'",
            "Wir sind müde." to "Wir sind müde.",
            "Wir sind + aggettivo müde." to "Wir sind + adjective müde.",
            "Usa il pronome wir e il verbo sein." to "Use the pronoun wir and the verb sein.",
            "Il tedesco ha tre generi: maschile (der), femminile (die), neutro (das). Il plurale usa sempre die." to "German has three genders: masculine (der), feminine (die), neuter (das). The plural always uses die.",
            "Il genere non si deduce sempre dal significato: das Mädchen (la ragazza) è neutro, der Name è maschile, die Tür è femminile." to "Gender cannot always be deduced from meaning: das Mädchen (the girl) is neuter, der Name is masculine, die Tür is feminine.",
            "Alcuni suffissi aiutano: -ung, -heit, -keit, -schaft, -tion sono normalmente femminili; -er, -ling, -ismus spesso maschili; -chen, -lein, -ment spesso neutri." to "Some suffixes help: -ung, -heit, -keit, -schaft, -tion are usually feminine; -er, -ling, -ismus often masculine; -chen, -lein, -ment often neuter.",
            "L'articolo determinativo al nominativo è der/die/das; al plurale è die per tutti e tre i generi." to "The definite article in the nominative is der/die/das; in the plural it is die for all three genders.",
            "L'articolo indeterminativo è ein per il maschile e il neutro, eine per il femminile; al plurale non si usa." to "The indefinite article is ein for masculine and neuter, eine for feminine; it is not used in the plural.",
            "Impara sempre il sostantivo insieme al suo articolo: non memorizzare solo la parola italiana." to "Always learn the noun together with its article: do not memorise only the English word.",
            "Il plurale non distingue il genere: l'articolo è sempre die." to "The plural does not distinguish gender: the article is always die.",
            "Al plurale non si usa l'articolo indeterminativo: die Männer, die Frauen, die Kinder." to "The indefinite article is not used in the plural: die Männer, die Frauen, die Kinder.",
            "Sono indizi, non leggi assolute: impara sempre l'articolo insieme alla parola." to "These are clues, not absolute rules: always learn the article together with the word.",
            "L'uomo è insegnante." to "The man is a teacher.",
            "La donna legge un libro." to "The woman is reading a book.",
            "Il bambino gioca in giardino." to "The child is playing in the garden.",
            "I libri sono nuovi." to "The books are new.",
            "La ragazza è mia sorella." to "The girl is my sister.",
            "Mädchen termina in -chen: è neutro, quindi das." to "Mädchen ends in -chen: it is neuter, so das.",
            "I sostantivi in -ung sono femminili: die Zeitung." to "Nouns ending in -ung are feminine: die Zeitung.",
            "Buch è neutro: das Buch." to "Buch is neuter: das Buch.",
            "Der, die, das: il genere va imparato con il sostantivo. Al plurale l'articolo è sempre die." to "Der, die, das: gender must be learned with the noun. In the plural the article is always die.",
            "___ Mann kommt aus Berlin." to "___ Mann kommt aus Berlin.",
            "Mann è maschile: der Mann." to "Mann is masculine: der Mann.",
            "___ Frau arbeitet hier." to "___ Frau arbeitet hier.",
            "Frau è femminile: die Frau." to "Frau is feminine: die Frau.",
            "___ Kind spielt im Garten." to "___ Kind spielt im Garten.",
            "Kind è neutro: das Kind." to "Kind is neuter: das Kind.",
            "___ Bücher sind neu." to "___ Bücher sind neu.",
            "Al plurale l'articolo è sempre die: die Bücher." to "In the plural the article is always die: die Bücher.",
            "___ Zeitung liegt auf dem Tisch." to "___ Zeitung liegt auf dem Tisch.",
            "Il suffisso -ung è femminile: die Zeitung." to "The suffix -ung is feminine: die Zeitung.",
            "___ Mädchen ist meine Schwester." to "___ Mädchen ist meine Schwester.",
            "Il suffisso -chen rende il sostantivo neutro: das Mädchen." to "The suffix -chen makes the noun neuter: das Mädchen.",
            "___ Schule ist groß." to "___ Schule ist groß.",
            "Schule è femminile: die Schule." to "Schule is feminine: die Schule.",
            "Scrivi solo l'articolo." to "Write only the article.",
            "___ Lehrer kommt gleich." to "___ Lehrer kommt gleich.",
            "Lehrer è maschile: der Lehrer." to "Lehrer is masculine: der Lehrer.",
            "___ Auto ist neu." to "___ Auto ist neu.",
            "Auto è neutro: das Auto." to "Auto is neuter: das Auto.",
            "Aggiungi l'articolo determinativo: Hund" to "Add the definite article: Hund",
            "Hund è maschile: der Hund." to "Hund is masculine: der Hund.",
            "Scrivi articolo e sostantivo." to "Write the article and the noun.",
            "Aggiungi l'articolo determinativo: Wohnung" to "Add the definite article: Wohnung",
            "Wohnung termina in -ung ed è femminile." to "Wohnung ends in -ung and is feminine.",
            "Traduci: «Il libro è interessante.»" to "Translate: 'The book is interesting.'",
            "Das Buch ist interessant." to "Das Buch ist interessant.",
            "Buch è neutro: das Buch." to "Buch is neuter: das Buch.",
            "Usa l'articolo das e l'aggettivo interessant." to "Use the article das and the adjective interessant.",
            "Al plurale l'articolo è sempre die, ma il sostantivo cambia in modi diversi." to "In the plural the article is always die, but the noun changes in different ways.",
            "Le desinenze più comuni sono -e (Tisch -> Tische), -en (Frau -> Frauen), -er (Kind -> Kinder), -s (Auto -> Autos) e nessuna desinenza (Lehrer -> Lehrer)." to "The most common endings are -e (Tisch -> Tische), -en (Frau -> Frauen), -er (Kind -> Kinder), -s (Auto -> Autos) and no ending (Lehrer -> Lehrer).",
            "Molti maschili e neutri prendono -e o -er; molti femminili prendono -en." to "Many masculine and neuter nouns take -e or -er; many feminine nouns take -en.",
            "Alcuni plurali aggiungono l'umlaut: Stadt -> Städte, Mann -> Männer, Buch -> Bücher." to "Some plurals add an umlaut: Stadt -> Städte, Mann -> Männer, Buch -> Bücher.",
            "Alcuni sostantivi si usano solo al plurale: die Eltern (i genitori), die Leute (la gente)." to "Some nouns are used only in the plural: die Eltern (parents), die Leute (people).",
            "Non esiste una regola unica: il plurale si impara insieme al singolare." to "There is no single rule: the plural is learned together with the singular.",
            "i bambini" to "children",
            "le donne" to "women",
            "gli uomini" to "men",
            "i libri" to "books",
            "le città" to "cities",
            "le auto" to "cars",
            "I bambini cantano nel parco." to "The children are singing in the park.",
            "Le donne lavorano qui." to "The women work here.",
            "I libri sono interessanti." to "The books are interesting.",
            "Le auto sono nuove." to "The cars are new.",
            "Gli insegnanti arrivano domani." to "The teachers arrive tomorrow.",
            "Kind forma il plurale con -er, non con -s." to "Kind forms the plural with -er, not -s.",
            "Auto è un prestito e forma il plurale con -s." to "Auto is a loanword and forms the plural with -s.",
            "Frau aggiunge -en: die Frauen." to "Frau adds -en: die Frauen.",
            "Plurale: articolo die + desinenza. Impara il plurale insieme al singolare." to "Plural: article die + ending. Learn the plural together with the singular.",
            "Plurale di Kind:" to "Plural of Kind:",
            "Kind -> Kinder: die Kinder." to "Kind -> Kinder: die Kinder.",
            "Plurale di Auto:" to "Plural of Auto:",
            "Auto è un prestito: die Autos." to "Auto is a loanword: die Autos.",
            "Plurale di Frau:" to "Plural of Frau:",
            "Frau -> Frauen." to "Frau -> Frauen.",
            "Plurale di Buch:" to "Plural of Buch:",
            "Buch -> Bücher, con umlaut e -er." to "Buch -> Bücher, with umlaut and -er.",
            "Plurale di Tisch:" to "Plural of Tisch:",
            "Tisch -> Tische." to "Tisch -> Tische.",
            "Plurale di Stadt:" to "Plural of Stadt:",
            "Stadt -> Städte, con umlaut e -e." to "Stadt -> Städte, with umlaut and -e.",
            "Scrivi il plurale: der Lehrer -> die ___" to "Write the plural: der Lehrer -> die ___",
            "Lehrer resta invariato: die Lehrer." to "Lehrer stays the same: die Lehrer.",
            "Scrivi solo il sostantivo al plurale." to "Write only the noun in the plural.",
            "Scrivi il plurale: der Mann -> die ___" to "Write the plural: der Mann -> die ___",
            "Mann -> Männer, con umlaut e -er." to "Mann -> Männer, with umlaut and -er.",
            "Scrivi il plurale: die Zeitung -> die ___" to "Write the plural: die Zeitung -> die ___",
            "Zeitung aggiunge -en: die Zeitungen." to "Zeitung adds -en: die Zeitungen.",
            "Trasforma al plurale: Das Kind spielt." to "Change to plural: Das Kind spielt.",
            "Il soggetto diventa plurale e il verbo prende la forma plurale." to "The subject becomes plural and the verb takes the plural form.",
            "Scrivi la frase completa al plurale." to "Write the complete sentence in the plural.",
            "Trasforma al plurale: Der Freund kommt." to "Change to plural: Der Freund kommt.",
            "Freund -> Freunde; kommt -> kommen." to "Freund -> Freunde; kommt -> kommen.",
            "Traduci: «I libri sono nuovi.»" to "Translate: 'The books are new.'",
            "Buch -> Bücher; il verbo sein al plurale è sind." to "Buch -> Bücher; the verb sein in the plural is sind.",
            "Usa die Bücher e sind." to "Use die Bücher and sind.",
            "Nella frase principale il verbo coniugato occupa la seconda posizione: Ich gehe heute ins Kino." to "In a main clause the conjugated verb occupies second position: Ich gehe heute ins Kino.",
            "Se la frase inizia con un'espressione di tempo o luogo, il soggetto passa dopo il verbo: Heute gehe ich ins Kino." to "If the sentence begins with a time or place expression, the subject moves after the verb: Heute gehe ich ins Kino.",
            "La domanda sì/no mette il verbo in prima posizione: Gehst du ins Kino?" to "A yes/no question puts the verb in first position: Gehst du ins Kino?",
            "La domanda con W-Wort segue lo schema W-Wort + verbo + soggetto: Wo arbeitest du?" to "A W-word question follows the pattern W-word + verb + subject: Wo arbeitest du?",
            "La negazione nicht sta dopo il verbo o l'aggettivo; kein sta davanti al sostantivo: Ich habe keine Zeit." to "The negation nicht comes after the verb or adjective; kein comes before the noun: Ich habe keine Zeit.",
            "Alcune preposizioni si fondono con l'articolo: am = an + dem (am Montag, am Abend), im = in + dem (im Kino), ins = in + das (ins Kino), zum = zu + dem, zur = zu + der. L'espressione fissa zu Hause significa «a casa»." to "Some prepositions merge with the article: am = an + dem (am Montag, am Abend), im = in + dem (im Kino), ins = in + das (ins Kino), zum = zu + dem, zur = zu + der. The fixed expression zu Hause means 'at home'.",
            "Il verbo resta sempre nella sua posizione: cambia solo ciò che lo precede." to "The verb always stays in its position: only what comes before it changes.",
            "Imparo il tedesco ogni giorno." to "I learn German every day.",
            "Oggi vado al cinema." to "Today I am going to the cinema.",
            "Dove lavori?" to "Where do you work?",
            "Hai tempo?" to "Do you have time?",
            "Non ho tempo." to "I don't have time.",
            "Il verbo deve restare in seconda posizione: se heute è all'inizio, il soggetto va dopo il verbo." to "The verb must stay in second position: if heute is at the beginning, the subject comes after the verb.",
            "Nella domanda con W-Wort il verbo viene subito dopo il W-Wort." to "In a W-word question the verb comes immediately after the W-word.",
            "La negazione di un sostantivo con articolo indeterminativo si fa con kein: keine Zeit." to "Negation of a noun with an indefinite article uses kein: keine Zeit.",
            "Verbo in seconda posizione. Domanda sì/no: verbo in prima. W-Wort + verbo + soggetto." to "Verb in second position. Yes/no question: verb first. W-word + verb + subject.",
            "Quale frase è corretta?" to "Which sentence is correct?",
            "Con heute all'inizio il verbo va in seconda posizione e il soggetto dopo: Heute gehe ich ..." to "With heute at the beginning the verb goes to second position and the subject after it: Heute gehe ich ...",
            "Con du il verbo wohnen diventa wohnst: Wo wohnst du?" to "With du the verb wohnen becomes wohnst: Wo wohnst du?",
            "Domanda sì/no con du: Hast du Zeit?" to "Yes/no question with du: Hast du Zeit?",
            "Con ich si usa habe." to "With ich, use habe.",
            "Con wir si usa lernen; il verbo resta in seconda posizione." to "With wir, use lernen; the verb stays in second position.",
            "Trasforma in domanda sì/no: Du kommst aus Italien. -> ___?" to "Turn into a yes/no question: Du kommst aus Italien. -> ___?",
            "Il verbo passa in prima posizione: Kommst du ...?" to "The verb moves to first position: Kommst du ...?",
            "Metti «Morgen» all'inizio: Ich fahre nach Berlin." to "Put 'Morgen' at the beginning: Ich fahre nach Berlin.",
            "Con Morgen all'inizio il verbo fahre resta in seconda posizione e ich passa dopo." to "With Morgen at the beginning the verb fahre stays in second position and ich moves after it.",
            "Scrivi la frase completa." to "Write the complete sentence.",
            "Trasforma in domanda con «Wo»: Du wohnst in Rom." to "Turn into a question with 'Wo': Du wohnst in Rom.",
            "Schema: Wo + wohnst + du?" to "Pattern: Wo + wohnst + du?",
            "Negazione: Ich habe ___ Zeit." to "Negation: Ich habe ___ Zeit.",
            "Zeit è femminile e il sostantivo è negato: keine Zeit." to "Zeit is feminine and the noun is negated: keine Zeit.",
            "Scrivi solo la parola negativa." to "Write only the negative word.",
            "Negazione: Das ist ___ richtig." to "Negation: Das ist ___ richtig.",
            "richtig è un aggettivo: si nega con nicht." to "richtig is an adjective: negate it with nicht.",
            "Traduci: «Oggi lavoro a casa.»" to "Translate: 'Today I work at home.'",
            "Con Heute all'inizio il verbo arbeite è in seconda posizione: Heute arbeite ich ..." to "With Heute at the beginning the verb arbeite is in second position: Heute arbeite ich ...",
            "Puoi anche scrivere Ich arbeite heute zu Hause." to "You can also write Ich arbeite heute zu Hause.",
            "Traduci: «Cosa bevi?»" to "Translate: 'What are you drinking?'",
            "Domanda con W-Wort: Was + trinkst + du?" to "W-word question: Was + trinkst + du?",
            "Usa il verbo trinken." to "Use the verb trinken.",
            "dopo verbo o aggettivo" to "after verb or adjective",
            "davanti al sostantivo" to "before the noun",
            "davanti a un avverbio o preposizione" to "before an adverb or preposition",
            "Soggetto + verbo + ..." to "Subject + verb + ...",
            "Tempo + verbo + soggetto + ..." to "Time + verb + subject + ...",
            "Verbo + soggetto + ...?" to "Verb + subject + ...?",
            "W-Wort + verbo + soggetto + ...?" to "W-word + verb + subject + ...?",
            "I verbi modali più importanti sono können (potere), müssen (dovere), dürfen (avere il permesso), wollen (volere), sollen (dovere/consiglio), mögen (piacere) e möchten (vorrei)." to "The most important modal verbs are können (can), müssen (must), dürfen (may), wollen (want), sollen (should), mögen (to like) and möchten (would like).",
            "Alla prima e alla terza persona singolare i modali non prendono la desinenza -t: ich kann, du kannst, er kann; ich muss, du musst, er muss." to "In the first and third person singular, modals do not take the -t ending: ich kann, du kannst, er kann; ich muss, du musst, er muss.",
            "Il modale coniugato sta in seconda posizione; l'infinito del verbo principale va alla fine: Ich kann heute nicht kommen." to "The conjugated modal stays in second position; the infinitive of the main verb goes to the end: Ich kann heute nicht kommen.",
            "Con i verbi riflessivi il pronome riflessivo sta tra il modale e l'infinito: Ich muss mich ausruhen. Du musst dich konzentrieren. Wir müssen uns beeilen." to "With reflexive verbs the reflexive pronoun comes between the modal and the infinitive: Ich muss mich ausruhen. Du musst dich konzentrieren. Wir müssen uns beeilen.",
            "La negazione si fa con nicht davanti all'infinito o con kein davanti a un sostantivo: Ich kann nicht kommen. Ich habe keine Zeit." to "Negation uses nicht before the infinitive or kein before a noun: Ich kann nicht kommen. Ich habe keine Zeit.",
            "möchten è la forma cortese di mögen e si usa per ordinare o chiedere: Ich möchte einen Kaffee." to "möchten is the polite form of mögen and is used to order or request: Ich möchte einen Kaffee.",
            "Osserva: ich e er/sie/es hanno la stessa forma, senza -t finale." to "Note: ich and er/sie/es share the same form, without a final -t.",
            "potere, essere capace" to "can, to be able to",
            "dovere, necessità" to "must, necessity",
            "avere il permesso" to "to be allowed to",
    )

