            "Quando rispondi giusto l'intervallo si allunga: 1, 3, 7, 16, 35, 75, 150, 300 giorni. Quando sbagli torna a domani." to "When you answer correctly the interval grows: 1, 3, 7, 16, 35, 75, 150, 300 days. When you make a mistake it returns to tomorrow.",

            "Il backup contiene tutti i profili (parole, ripassi, test, progressi). " to "The backup contains all profiles (words, reviews, tests, progress). ",

