            "Facoltativo: scegli un provider e incolla la chiave. " to "Optional: choose a provider and paste the key. ",

            "Resta sul dispositivo e viene inviato solo ai provider AI quando generi contenuti. Vuoto = nessuna personalizzazione." to "Stays on the device and is only sent to AI providers when you generate content. Empty = no personalization.",

            "L'AI usa queste informazioni per scegliere esempi, esercizi e vocabolario adatti a te." to "AI uses this information to choose examples, exercises and vocabulary suited to you.",

            "Come usare il TUO documento Google:\n\n1. Apri Google Docs e crea un documento\n2. Scrivi la guida (usa i Titoli)\n3. Condividi → Chiunque abbia il link → Visualizzatore\n4. Copia l'indirizzo e incollalo qui" to "How to use YOUR Google document:\n\n1. Open Google Docs and create a document\n2. Write the guide (use Headings)\n3. Share → Anyone with the link → Viewer\n4. Copy the address and paste it here",
            "Come creare il TUO vocabolario su GitHub:\n\n1. Vai su github.com e accedi (o crea un account gratis)\n2. Crea un repository pubblico\n3. Carica un file vokabeln.json\n4. Copia l'URL Raw e incollalo qui\n\nFormato: {\"words\":[{\"id\":\"1\",\"german\":\"der Hund\", \"italian\":\"il cane\",\"level\":\"A1\",\"lesson\":1}]}" to "How to create YOUR vocabulary on GitHub:\n\n1. Go to github.com and sign in (or create a free account)\n2. Create a public repository\n3. Upload a vokabeln.json file\n4. Copy the Raw URL and paste it here\n\nFormat: {\"words\":[{\"id\":\"1\",\"german\":\"der Hund\", \"italian\":\"il cane\",\"level\":\"A1\",\"lesson\":1}]}",

