            "L'AI usa questa descrizione per scegliere esempi, esercizi, lezioni e vocabolario adatti a te. Se lavori in ambito sanitario, scrivilo qui: è una personalizzazione come le altre. Puoi cambiarla quando vuoi." to "AI uses this description to choose examples, exercises, lessons and vocabulary suited to you. If you work in healthcare, write it here: it's a personalization like any other. You can change it whenever you want.",

