            "„Aspetto l'autobus.“" to "\"I'm waiting for the bus.\"",
            "„Mi chiedi dove abito.“" to "\"You ask me where I live.\"",
            "Fragewort in prima posizione, verbo in seconda." to "Question word in first position, conjugated verb in second.",
            "„Dove studi?“" to "\"Where do you study?\"",
            "„Quando arrivai, lui aveva già mangiato.“" to "\"When I arrived, he had already eaten.\"",
            "„Il nome del paziente è Müller.“" to "\"The patient's name is Müller.\"",
            "„La cosa più importante è la salute.“" to "\"The most important thing is health.\"",
            "Non si mescolano: o daran (senza nome) o preposizione + nome." to "Don't mix them: either daran (without noun) or preposition + noun.",
            "„Più leggo, meglio capisco.“" to "\"The more I read, the better I understand.\"",
            "„Il problema si può risolvere facilmente.“" to "\"The problem can be solved easily.\"",
            "„Il negozio è aperto.“" to "\"The shop is open.\"",
            "derselbe/dieselbe/dasselbe = la stessa cosa/la stessa persona (identità): declinazione come l'articolo determinativo (derselbe, dieselbe, dasselbe, derselben, demselben)." to "derselbe/dieselbe/dasselbe = the same thing/person (identity): declined like the definite article (derselbe, dieselbe, dasselbe, derselben, demselben).",
            "„Do il libro a lui.“" to "\"I give him the book.\"",

            "„Il medico ha una visita importante.“" to "„Il medico ha una visita importante.“",
            "stato irrealizzabile" to "unreal state",
            "possibilità cortese" to "polite possibility",
            "„Se avessi tempo, verrei.“" to "„Se avessi tempo, verrei.“",
            "Verbi con preposizione + accusativo: warten auf, denken an, sich interessieren für, sich freuen auf/über, sprechen über, bitten um, danken für, sich kümmern um, teilnehmen an (+Dat)." to "Verbs with preposition + accusative: warten auf, denken an, sich interessieren für, sich freuen auf/über, sprechen über, bitten um, danken für, sich kümmern um, teilnehmen an (+Dat).",
            "Verbi con preposizione + dativo: gehören zu, teilnehmen an, sich gewöhnen an (+Akk), sich erinnern an (+Akk)." to "Verbs with preposition + dative: gehören zu, teilnehmen an, sich gewöhnen an (+Akk), sich erinnern an (+Akk).",
            "Aspetto il treno." to "I'm waiting for the train.",
            "Pensa alla sua famiglia." to "He thinks about his family.",
            "Si interessa di musica." to "She is interested in music.",
            "Non vediamo l'ora del weekend." to "We are looking forward to the weekend.",
            "alle = tutti, einige = alcuni, mehrere = parecchi, manche = alcuni (non tutti). Si declinano come aggettivi senza articolo." to "alle = everyone, einige = some, mehrere = several, manche = some (not all). They are declined like adjectives without an article.",
            "jemand/niemand + etwas/nichts si usano anche come oggetto: Ich habe jemanden gesehen. / Ich habe nichts verstanden." to "jemand/niemand + etwas/nichts are also used as objects: Ich habe jemanden gesehen. / Ich habe nichts verstanden.",
            "come aggettivo senza articolo" to "like an adjective without an article",
            "alcuni (non tutti)" to "some (not all)",
            "jemand e niemand si usano per lo più al singolare; per il plurale si usano alle/einige/mehrere." to "jemand and niemand are mostly used in the singular; for the plural use alle/einige/mehrere.",
            "Ein paar Studenten sind da." to "A few students are there.",
            "jemand è nominativo; se è oggetto: jemanden." to "jemand is nominative; if it is an object: jemanden.",
            "man è sempre soggetto impersonale (nominativo)." to "man is always an impersonal subject (nominative).",
            "nichts è invariabile: nichts gesehen, non nichts-en." to "nichts is invariable: nichts gesehen, not nichts-en.",
            "man = si impersonale; jemand/niemand + qualcuno/nessuno; etwas/nichts = qualcosa/niente (invariabili)." to "man = impersonal 'one'; jemand/niemand = someone/no one; etwas/nichts = something/nothing (invariable).",
            "„Qualcuno ha chiamato?“" to "„Qualcuno ha chiamato?“",
            "Si introduce con: Ich weiß nicht, ...; Ich frage mich, ...; Er fragt, ...; Ich möchte wissen, ..." to "Introduced by: Ich weiß nicht, ...; Ich frage mich, ...; Er fragt, ...; Ich möchte wissen, ...",
            "Dopo ob il verbo va alla fine." to "After ob the verb goes to the end.",
            "Dopo il W-Wort il verbo va alla fine." to "After the W-word the verb goes to the end.",
            "La frase indiretta non ha punto interrogativo (se la principale è affermativa)." to "The indirect clause has no question mark (if the main clause is declarative).",
            "Domanda indiretta = verbo alla fine; ob per sì/no, W-Wort per le altre." to "Indirect question = verb at the end; ob for yes/no, W-word for others.",
            "dove (direzione)" to "where to (direction)",
            "was für + articolo indeterminativo." to "was für + indefinite article.",
            "Con i pronomi personali queste preposizioni reggono il dativo." to "Con i pronomi personali queste preposizioni reggono il dativo.",
            "Non si mescolano: genitivo con sostantivo, dativo con pronome." to "Non si mescolano: genitivo con sostantivo, dativo con pronome.",
