            "L'infinito del verbo principale va alla fine: ... Deutsch sprechen." to "The infinitive of the main verb goes to the end: ... Deutsch sprechen.",
            "Alla terza persona singolare il modale non prende -t: er kann." to "In the third person singular the modal does not take -t: er kann.",
            "Non si accumulano nicht e kein: per negare un sostantivo basta kein." to "Do not combine nicht and kein: to negate a noun, kein is enough.",
            "Modale in seconda posizione, infinito alla fine. ich/er: kann, muss, will (senza -t)." to "Modal in second position, infinitive at the end. ich/er: kann, muss, will (without -t).",
            "Ich ___ gut schwimmen." to "Ich ___ gut schwimmen.",
