            "Metti l'infinito alla fine: Ich kann / gut / kochen." to "Put the infinitive at the end: Ich kann / gut / kochen.",
            "Il modale kann è in seconda posizione, l'infinito kochen alla fine." to "The modal kann is in second position, the infinitive kochen at the end.",
            "Trasforma in domanda sì/no: Du kannst mir helfen." to "Turn into a yes/no question: Du kannst mir helfen.",
            "Il modale va in prima posizione: Kannst du ...?" to "The modal goes to first position: Kannst du ...?",
            "Ich ___ (möchten) einen Kaffee." to "Ich ___ (möchten) einen Kaffee.",
            "möchten: ich möchte." to "möchten: ich möchte.",
            "Traduci: «Devo andare a casa.»" to "Translate: 'I have to go home.'",
            "müssen + infinito alla fine: muss ... gehen." to "müssen + infinitive at the end: muss ... gehen.",
            "Usa nach Hause per «a casa»." to "Use nach Hause for 'home'.",
            "Molti verbi tedeschi hanno un prefisso separabile: auf-, an-, aus-, ein-, mit-, zu-, ab-, vor-, zurück-, fern-." to "Many German verbs have a separable prefix: auf-, an-, aus-, ein-, mit-, zu-, ab-, vor-, zurück-, fern-.",
            "Nella frase principale il verbo coniugato resta in seconda posizione e il prefisso va alla fine: Ich stehe um 6 Uhr auf." to "In a main clause the conjugated verb stays in second position and the prefix goes to the end: Ich stehe um 6 Uhr auf.",
            "All'infinito e nel participio passato il prefisso resta unito al verbo: aufstehen, aufgestanden." to "In the infinitive and past participle the prefix stays attached to the verb: aufstehen, aufgestanden.",
            "I prefissi be-, ge-, er-, ver-, ent-, emp-, miss- non si separano: verstehen, bekommen, erklären." to "The prefixes be-, ge-, er-, ver-, ent-, emp-, miss- do not separate: verstehen, bekommen, erklären.",
            "Con i verbi separabili il participio passato mette ge tra prefisso e verbo: aufstehen -> aufgestanden." to "With separable verbs the past participle puts ge between prefix and verb: aufstehen -> aufgestanden.",
            "Avverbi come gerne (volentieri), oft e immer stanno prima del prefisso separabile: Ich rufe dich gerne an." to "Adverbs like gerne (gladly), oft and immer come before the separable prefix: Ich rufe dich gerne an.",
            "Il prefisso separabile si riconosce perché ha un significato proprio e resta in fondo alla frase." to "A separable prefix is recognisable because it has its own meaning and stays at the end of the sentence.",
            "non si separa" to "does not separate",
            "Mi alzo alle 6." to "I get up at 6 o'clock.",
            "Il corso inizia alle 10." to "The course starts at 10 o'clock.",
            "Facciamo la spesa al supermercato." to "We do the shopping at the supermarket.",
            "Vieni con noi?" to "Are you coming with us?",
            "La sera guarda la TV." to "In the evening he watches TV.",
            "Il verbo coniugato va in seconda posizione, il prefisso alla fine." to "The conjugated verb goes to second position, the prefix at the end.",
            "anfangen è irregolare: fange ... an." to "anfangen is irregular: fange ... an.",
            "Nel participio passato il prefisso resta unito: aufgestanden." to "In the past participle the prefix stays attached: aufgestanden.",
            "Prefisso separabile: verbo in seconda posizione, prefisso in fondo. Nel participio: aufgestanden." to "Separable prefix: verb in second position, prefix at the end. In the participle: aufgestanden.",
            "Ich ___ um 7 Uhr ___." to "Ich ___ um 7 Uhr ___.",
            "aufstehen: Ich stehe um 7 Uhr auf." to "aufstehen: Ich stehe um 7 Uhr auf.",
