            "Er sieht abends ___." to "Er sieht abends ___.",
            "Il prefisso di fernsehen è fern." to "The prefix of fernsehen is fern.",
            "Fai una frase principale: aufstehen / ich / um 7 Uhr." to "Make a main clause: aufstehen / ich / um 7 Uhr.",
            "Il verbo coniugato stehe è in seconda posizione, auf alla fine." to "The conjugated verb stehe is in second position, auf at the end.",
            "Fai una frase principale: anfangen / der Kurs / um 9 Uhr." to "Make a main clause: anfangen / der Kurs / um 9 Uhr.",
            "anfangen è irregolare: fängt ... an." to "anfangen is irregular: fängt ... an.",
            "Participio passato di aufstehen." to "Past participle of aufstehen.",
            "Il participio è aufgestanden: ge tra prefisso e verbo." to "The participle is aufgestanden: ge between prefix and verb.",
            "Traduci: «Vengo volentieri con voi.»" to "Translate: 'I am happy to come with you.'",
            "mitkommen: Ich komme ... mit; gerne = volentieri." to "mitkommen: Ich komme ... mit; gerne = gladly.",
            "Usa mitkommen e gerne." to "Use mitkommen and gerne.",
            "Le preposizioni in, an, auf, unter, über, vor, hinter, neben, zwischen possono reggere dativo o accusativo." to "The prepositions in, an, auf, unter, über, vor, hinter, neben, zwischen can take either the dative or the accusative.",
            "Con Wo? (dove? stato in luogo) si usa il dativo: Ich bin in der Küche." to "With Wo? (where? location) the dative is used: Ich bin in der Küche.",
            "Con Wohin? (dove? moto a luogo) si usa l'accusativo: Ich gehe in die Schule." to "With Wohin? (where to? movement) the accusative is used: Ich gehe in die Schule.",
            "Le contrazioni più comuni sono im, am, ins, ans, zum, zur, beim, vom: ins Kino, am Tisch, zur Schule." to "The most common contractions are im, am, ins, ans, zum, zur, beim, vom: ins Kino, am Tisch, zur Schule.",
            "Con città e paesi si usa spesso nach: nach Berlin, nach Italien. Con le persone e alcuni luoghi si usa zu: zum Arzt, zur Lehrerin." to "With cities and countries, nach is often used: nach Berlin, nach Italien. With people and some places, zu is used: zum Arzt, zur Lehrerin.",
            "La preposizione è la stessa: cambia il caso e quindi l'articolo." to "The preposition stays the same: the case changes, and therefore the article.",
            "Sono in cucina." to "I am in the kitchen.",
            "Vado a scuola." to "I am going to school.",
            "Il libro è sul tavolo." to "The book is on the table.",
            "Metto il libro sul tavolo." to "I put the book on the table.",
            "Andiamo a Berlino." to "We are going to Berlin.",
            "Wohin? richiede l'accusativo: in die Schule." to "Wohin? requires the accusative: in die Schule.",
            "Wo? richiede il dativo: in der Küche." to "Wo? requires the dative: in der Küche.",
            "Wo? richiede il dativo: in der Schule." to "Wo? requires the dative: in der Schule.",
            "Con le istituzioni si usa zu + dativo: zu der Schule -> zur Schule." to "With institutions, use zu + dative: zu der Schule -> zur Schule.",
            "Wo? -> dativo. Wohin? -> accusativo. La preposizione non cambia, cambia l'articolo." to "Wo? -> dative. Wohin? -> accusative. The preposition doesn't change, the article does.",
            "Ich gehe ___ Schule." to "Ich gehe ___ Schule.",
            "Wohin? -> accusativo: in die Schule." to "Wohin? -> accusative: in die Schule.",
            "Ich bin ___ Schule." to "Ich bin ___ Schule.",
