            "Wohin? -> accusativo: auf den Tisch." to "Wohin? -> accusative: auf den Tisch.",
            "Wir wohnen ___ Berlin." to "Wir wohnen ___ Berlin.",
            "Con le città si usa in: in Berlin." to "With cities, use in: in Berlin.",
            "Ich gehe ___ Kino." to "Ich gehe ___ Kino.",
            "in + das = ins: ins Kino." to "in + das = ins: ins Kino.",
            "Sie geht ___ Lehrerin." to "Sie geht ___ Lehrerin.",
            "zu + der = zur: zur Lehrerin gehen." to "zu + der = zur: zur Lehrerin gehen.",
            "Wir fahren ___ Italien." to "Wir fahren ___ Italien.",
            "Con i paesi si usa nach: nach Italien." to "With countries, use nach: nach Italien.",
            "Wo? Forma la frase: Ich bin / Schule." to "Wo? Form the sentence: Ich bin / Schule.",
            "Stato in luogo: in + dativo -> in der Schule." to "Location: in + dative -> in der Schule.",
            "Wohin? Forma la frase: Ich gehe / Kino." to "Wohin? Form the sentence: Ich gehe / Kino.",
            "Moto a luogo: in + das = ins." to "Movement: in + das = ins.",
            "Das Bild hängt ___ Wand. (an + dativo)" to "Das Bild hängt ___ Wand. (an + dative)",
            "Wand è femminile; con Wo? si usa il dativo: an der Wand." to "Wand is feminine; with Wo? the dative is used: an der Wand.",
            "Scrivi preposizione e articolo." to "Write the preposition and the article.",
            "Traduci: «Vado a casa.»" to "Translate: 'I am going home.'",
            "«A casa» come moto si dice nach Hause." to "'Home' as movement is nach Hause.",
            "Usa nach Hause." to "Use nach Hause.",
            "um si usa con l'ora: um 8 Uhr." to "um is used with clock times: um 8 Uhr.",
            "am si usa con i giorni e le date: am Montag, am 1. Mai." to "am is used with days and dates: am Montag, am 1. Mai.",
            "im si usa con mesi e stagioni: im Januar, im Sommer." to "im is used with months and seasons: im Januar, im Sommer.",
            "in si usa per un periodo futuro: in einer Woche, in zwei Tagen." to "in is used for a future period: in einer Woche, in zwei Tagen.",
            "seit + dativo indica «da/per» un periodo che continua; vor + dativo indica «fa»; nach + dativo indica «dopo»." to "seit + dative means 'for/since' an ongoing period; vor + dative means 'ago'; nach + dative means 'after'.",
            "am e im sono contrazioni di an + dem e in + dem." to "am and im are contractions of an + dem and in + dem.",
