            "Il corso inizia alle 9." to "The course starts at 9 o'clock.",
            "Vivo a Berlino da un anno." to "I have been living in Berlin for a year.",
            "Dopo mangiato andiamo a passeggiare." to "After eating we go for a walk.",
            "I giorni della settimana vogliono am: am Montag." to "Days of the week take am: am Montag.",
            "I mesi vogliono im: im Januar." to "Months take im: im Januar.",
            "seit regge il dativo: seit einem Jahr." to "seit takes the dative: seit einem Jahr.",
            "um + ora, am + giorno, im + mese/stagione, in + futuro, seit/vor + dativo." to "um + time, am + day, im + month/season, in + future, seit/vor + dative.",
            "___ Montag habe ich frei." to "___ Montag habe ich frei.",
