            "___ dem Essen gehen wir spazieren." to "___ dem Essen gehen wir spazieren.",
            "«Dopo il pasto» si dice nach dem Essen." to "'After the meal' is nach dem Essen.",
            "Traduci: «Aspetto da un'ora.»" to "Translate: 'I have been waiting for an hour.'",
            "seit + dativo: seit einer Stunde." to "seit + dative: seit einer Stunde.",
