            "da/per, con dativo" to "for/since, with dative",
            "fa, con dativo" to "ago, with dative",
            "dopo, con dativo" to "after, with dative",
            "fino a" to "until",
            "a partire da" to "starting from",
            "La forma du si costruisce dalla radice del verbo senza -st: machen -> Mach!; la -e finale è facoltativa." to "The du form is built from the verb stem without -st: machen -> Mach!; the final -e is optional.",
            "La forma ihr usa la radice + -t: Macht das!" to "The ihr form uses the stem + -t: Macht das!",
            "La forma Sie usa l'infinito + Sie: Machen Sie das!" to "The Sie form uses the infinitive + Sie: Machen Sie das!",
            "La forma wir usa l'infinito + wir: Gehen wir!" to "The wir form uses the infinitive + wir: Gehen wir!",
            "I verbi con prefisso separabile mettono il prefisso in fondo: Steh auf!; le forme irregolari più importanti sono sein -> sei, haben -> hab, werden -> werde." to "Separable-prefix verbs put the prefix at the end: Steh auf!; the most important irregular forms are sein -> sei, haben -> hab, werden -> werde.",
            "Con i verbi riflessivi il pronome riflessivo segue l'imperativo: Wasch dich! Setzt euch! Setzen Sie sich!" to "With reflexive verbs the reflexive pronoun follows the imperative: Wasch dich! Setzt euch! Setzen Sie sich!",
            "Il pronome du, ihr e wir di solito non si scrive; con Sie invece si scrive sempre." to "The pronouns du, ihr and wir are usually not written; with Sie, however, it is always written.",
            "Per favore, chiudi la porta!" to "Please close the door!",
            "Venite con noi!" to "Come with us!",
            "Aspetti qui, per favore!" to "Please wait here!",
            "Stai zitto!" to "Be quiet!",
            "Alzati alle 7!" to "Get up at 7!",
            "Per dare un ordine non si usa il pronome du né la forma -st." to "To give an order, neither the pronoun du nor the -st form is used.",
            "L'imperativo di sein alla seconda persona singolare è sei." to "The imperative of sein in the second person singular is sei.",
            "Nell'imperativo il verbo non prende -st e il prefisso va in fondo." to "In the imperative the verb does not take -st and the prefix goes to the end.",
            "du: radice; ihr: radice + t; Sie: infinito + Sie; wir: infinito + wir. sein -> sei." to "du: stem; ihr: stem + t; Sie: infinitive + Sie; wir: infinitive + wir. sein -> sei.",
            "Imperativo du di machen:" to "Imperative du of machen:",
            "La forma du di machen è Mach!" to "The du form of machen is Mach!",
            "Imperativo du di kommen:" to "Imperative du of kommen:",
            "La forma du di kommen è Komm!" to "The du form of kommen is Komm!",
            "Imperativo ihr di gehen:" to "Imperative ihr of gehen:",
            "La forma ihr aggiunge -t: Geht!" to "The ihr form adds -t: Geht!",
            "Imperativo Sie di warten:" to "Imperative Sie of warten:",
            "Con Sie si usa l'infinito + Sie: Warten Sie!" to "With Sie use the infinitive + Sie: Warten Sie!",
            "Imperativo du di sein:" to "Imperative du of sein:",
            "L'imperativo di sein è sei." to "The imperative of sein is sei.",
            "___ bitte leise! (sein, du)" to "___ bitte leise! (sein, du)",
            "La forma du di sein all'imperativo è Sei." to "The du imperative form of sein is Sei.",
            "___ Sie bitte hier! (warten)" to "___ Sie bitte hier! (warten)",
            "Con Sie: Warten Sie bitte hier!" to "With Sie: Warten Sie bitte hier!",
            "___ auf! (aufstehen, du)" to "___ auf! (aufstehen, du)",
            "aufstehen: Steh auf!" to "aufstehen: Steh auf!",
            "Trasforma in imperativo du: Du gehst nach Hause." to "Turn into du imperative: Du gehst nach Hause.",
            "La forma du di gehen è Geh; il resto della frase resta uguale." to "The du form of gehen is Geh; the rest of the sentence stays the same.",
            "Scrivi l'ordine completo." to "Write the complete command.",
            "Trasforma in imperativo ihr: Ihr kommt mit." to "Turn into ihr imperative: Ihr kommt mit.",
            "La forma ihr di kommen è Kommt; il prefisso mit va in fondo." to "The ihr form of kommen is Kommt; the prefix mit goes to the end.",
            "Trasforma in imperativo Sie: Sie machen die Tür zu." to "Turn into Sie imperative: Sie machen die Tür zu.",
            "Con Sie: Machen Sie ...; il prefisso zu va in fondo." to "With Sie: Machen Sie ...; the prefix zu goes to the end.",
            "Traduci: «Per favore, siediti!»" to "Translate: 'Please sit down!'",
            "sich setzen: Setz dich! La forma du di setzen è setz." to "sich setzen: Setz dich! The du form of setzen is setz.",
            "Usa bitte e il riflessivo dich." to "Use bitte and the reflexive dich.",
            "radice (senza -st)" to "stem (without -st)",
            "radice + -t" to "stem + -t",
            "infinito + Sie" to "infinitive + Sie",
