            "La seconda frase dice «Er macht zuerst Kaffee»: prima il caffè, poi la doccia." to "The second sentence says \"Er macht zuerst Kaffee\": coffee first, then a shower.",
            "Perché chiude la finestra?" to "Why does he close the window?",
