            "Weil es kalt ist" to "Because it is cold",
            "Il vento entra dal buco: «Der Wind kommt durch das Loch»." to "The wind comes in through the hole: \"Der Wind kommt durch das Loch\".",
            "Stessi personaggi, stessa casa: cambia solo una cosa (un pacco). Il resto del vocabolario si ripete, e capire diventa facile." to "Same characters, same house: only one thing changes (a package). The rest of the vocabulary repeats, and understanding becomes easy.",
            "Le stesse strutture in una scena reale: 1000 parole usuali coprono l'85% della conversazione quotidiana." to "The same structures in a real scene: 1,000 common words cover 85% of everyday conversation.",
            "Racconto breve di viaggio: ascolto, orientamento e piccole decisioni in stazione." to "A short travel story: listening, getting around and small decisions at the station.",
            "Perfekt in una scena reale: le azioni finite raccontate con le parole di tutti i giorni." to "Perfekt in a real scene: completed actions told with everyday words.",
            "Dopo la visita: la ricetta, la farmacia e le istruzioni. Il tedesco che serve davvero quando si è pazienti." to "After the visit: the prescription, the pharmacy and instructions. The German you really need as a patient.",
            "Trovare casa: offerte, appuntamenti, prime impressioni e una decisione importante." to "Finding a home: offers, appointments, first impressions and an important decision.",
            "La stessa ricerca, un passo dopo: la chiamata del proprietario e la scelta finale." to "The same search, one step later: the landlord's call and the final choice.",
            "Una pratica amministrativa: richieste, documenti, scadenze e toni formali." to "An administrative matter: requests, documents, deadlines and formal tone.",
            "La stessa pratica, un passo avanti: il colloquio allo sportello. Passivo, Konjunktiv e connettivi in una scena che si ripete nella vita vera." to "The same matter, one step further: the conversation at the counter. Passive, Konjunktiv and connectors in a scene that repeats in real life.",
