            "Cosa deve fare Moritz?" to "What does Moritz have to do?",
            "«Bitte unterschreiben Sie hier»: deve firmare, non pagare." to "\"Bitte unterschreiben Sie hier\": he must sign, not pay.",
            "Cosa c'è nel pacco?" to "What is in the package?",
            "L'ultima frase lo dice: «Im Paket ist ein neues Buch»." to "The last sentence says so: \"Im Paket ist ein neues Buch\".",
            "Il sabato Lena va al mercato." to "On Saturdays Lena goes to the market.",
            "Compra pane, formaggio e mele." to "She buys bread, cheese and apples.",
            "Il venditore non ha più mele." to "The seller has no more apples.",
            "Per questo prende le pere." to "That's why she takes pears.",
            "Poiché compra tanto, le serve una borsa." to "Since she buys a lot, she needs a bag.",
            "Più tardi rientra a casa in bici." to "Later she rides her bike home.",
            "La pista ciclabile è un grande aiuto." to "The bike path is a great help.",
