            "«Darum nimmt sie Birnen»: pere al posto delle mele." to "\"Darum nimmt sie Birnen\": pears instead of apples.",
            "Venerdì Lena va a Colonia." to "On Friday Lena goes to Cologne.",
            "Compra un biglietto alla stazione." to "She buys a ticket at the station.",
            "La macchinetta non accetta la carta." to "The machine doesn't accept cards.",
            "Per questo paga con le monete." to "That's why she pays with coins.",
