            "A Colonia visita un'amica." to "In Cologne she visits a friend.",
            "Tornano insieme al mercato coperto." to "They go back together to the covered market.",
            "Dove va Lena?" to "Where is Lena going?",
            "Prima frase: «Am Freitag fährt Lena nach Köln»." to "First sentence: \"Am Freitag fährt Lena nach Köln\".",
            "Perché paga con monete?" to "Why does she pay with coins?",
            "La macchinetta non accetta la carta, quindi servono monete." to "The machine doesn't accept cards, so coins are needed.",
            "Dove aspetta il treno?" to "Where is the train waiting?",
            "«Auf Gleis drei wartet schon der Zug»." to "\"Auf Gleis drei wartet schon der Zug\".",
            "La settimana scorsa Marco ha avuto un'eruzione sulla gamba." to "Last week Marco got a rash on his leg.",
            "Ha fissato in fretta un appuntamento dal dermatologo." to "He quickly made an appointment with the dermatologist.",
            "Il medico ha guardato la pelle con attenzione." to "The doctor examined the skin carefully.",
            "«Ha sudato molto nel weekend?», chiese." to "\"Did you sweat a lot over the weekend?\", he asked.",
            "«Un po'», disse Marco." to "\"A little\", said Marco.",
            "Il medico ha detto che l'eruzione è innocua." to "The doctor said the rash was harmless.",
            "Ha dato una pomata." to "He gave him an ointment.",
            "Il prurito è sparito presto." to "The itching soon disappeared.",
            "Oggi Marco sta di nuovo bene." to "Today Marco is well again.",
            "Cosa ha avuto Marco?" to "What did Marco have?",
            "«Einen Ausschlag am Bein»: un'eruzione sulla gamba." to "\"Einen Ausschlag am Bein\": a rash on the leg.",
            "Chi ha visto?" to "Who did he see?",
            "Hautarzt = dermatologo; Zahnarzt è il dentista." to "Hautarzt = dermatologist; Zahnarzt is the dentist.",
            "Cosa gli ha dato il medico?" to "What did the doctor give him?",
            "«Er hat eine Salbe gegeben»: una pomata." to "\"Er hat eine Salbe gegeben\": an ointment.",
            "Marco ha ricevuto una ricetta dal dermatologo." to "Marco received a prescription from the dermatologist.",
            "Va nella farmacia all'angolo." to "He goes to the pharmacy on the corner.",
            "La farmacista legge la ricetta con attenzione." to "The pharmacist reads the prescription carefully.",
            "Dice: «La pomata deve usarla due volte al giorno.»" to "She says: \"You must use the ointment twice a day.\"",
            "Marco chiede: «Posso fare la doccia con questa?»" to "Marco asks: \"Can I shower with this on?\"",
            "«Sì, ma non troppo calda», risponde." to "\"Yes, but not too hot\", she replies.",
