            "I possessivi hanno una radice (**mein-, dein-, sein-, ihr-, unser-, euer-**) e prendono le stesse desinenze di ein: mein Vater, meine Mutter, mein Kind, meine Eltern. All'accusativo maschile aggiungono **-en**: meinen Vater, seinen Bruder, unseren Hund." to "I possessivi hanno una radice (**mein-, dein-, sein-, ihr-, unser-, euer-**) e prendono le stesse desinenze di ein: mein Vater, meine Mutter, mein Kind, meine Eltern. All'accusative masculine aggiungono **-en**: meinen Vater, seinen Bruder, unseren Hund.",
