            "Per lo stato risultante si usa sein + Partizip II, non il passivo perfetto." to "For the resulting state use sein + Partizip II, not the perfect passive.",
            "Die Tür wird geöffnet. (= stato)" to "Die Tür wird geöffnet. (= state)",
            "werden = azione in corso; sein = stato risultante." to "werden = ongoing action; sein = resulting state.",
            "Zustandspassiv: sein + Partizip II, senza worden." to "Stative passive: sein + Partizip II, without worden.",
            "Senza particella il tono è più secco; doch aggiunge insistenza." to "Without the particle the tone is drier; doch adds insistence.",
