            "dieses + sostantivo, oppure dies + verbo (senza sostantivo)." to "dieses + noun, or dies + verb (without noun).",
            "dadurch occupa la prima posizione: verbo in seconda." to "dadurch takes first position: verb in second.",
            "Se si omette il sostantivo, si usa dies/das (neutro)." to "If the noun is omitted, use dies/das (neuter).",
