            "Perfetto. Si accomodi pure. La terapista arriva tra poco." to "Perfect. Please have a seat. The therapist will be here shortly.",
            "Grazie. Quanto dura la prima seduta?" to "Thank you. How long does the first session last?",
            "Circa 45 minuti. Facciamo l'anamnesi e un esame." to "About 45 minutes. We'll take your medical history and do an assessment.",
            "Buongiorno, sono il signor Müller, il suo fisioterapista. Cosa la porta da noi?" to "Good morning, I'm Mr Müller, your physiotherapist. What brings you here?",
            "Ho mal di schiena da tre settimane, soprattutto la mattina." to "I've had back pain for three weeks, especially in the morning.",
            "Mi può indicare dove fa male esattamente?" to "Can you show me exactly where it hurts?",
            "Qui, in basso alla schiena. A volte irradia alla gamba." to "Here, in the lower back. Sometimes it radiates to the leg.",
            "Ha intorpidimento o formicolio alla gamba?" to "Do you have numbness or tingling in your leg?",
            "No, solo dolore. Ma di notte mi sveglio a volte." to "No, just pain. But I sometimes wake up at night.",
            "Capisco. Fa sport? Com'è la sua giornata lavorativa?" to "I understand. Do you exercise? What is your workday like?",
            "Sto molto alla scrivania. Ma corro due volte a settimana." to "I sit at a desk a lot. But I run twice a week.",
            "Bene. Allora controlliamo la mobilità. Si pieghi in avanti per favore." to "Good. Then let's check your mobility. Please bend forward.",
            "Fisioterapia Huber, buongiorno." to "Huber Physiotherapy, good morning.",
            "Buongiorno, vorrei fissare un appuntamento." to "Good morning, I would like to make an appointment.",
            "Volentieri. Ha un'impegnativa del medico?" to "Certainly. Do you have a doctor's referral?",
            "Sì, ce l'ho. Ho dolore al ginocchio da una settimana." to "Yes, I do. I've had knee pain for a week.",
            "Capisco. Ha tempo la mattina o il pomeriggio?" to "I see. Are you available in the morning or afternoon?",
            "Il pomeriggio sarebbe meglio. Dalle 14." to "The afternoon would be better. From 2 pm onwards.",
            "Domani alle 14:30 sarebbe libero. Va bene?" to "Tomorrow at 2:30 pm is available. Does that work?",
            "Sì, perfetto. Grazie mille!" to "Yes, perfect. Thank you very much!",
            "Porti l'impegnativa e abbigliamento comodo." to "Please bring the referral and comfortable clothing.",
            "Allora, hai fatto le ferie quest'anno?" to "So, have you taken any holidays this year?",
            "Sì, a gennaio ero in Südtirol. Le montagne sono da sogno." to "Yes, in January I was in South Tyrol. The mountains are a dream.",
            "E? Ci sono buone patate lì? I canederli sono spettacolari." to "And? Are there good potatoes there? The dumplings are amazing.",
            "Assolutamente. E devi provare lo strudel di topfen. Non quark, topfen!" to "Absolutely. And you must try the Topfen strudel. Not quark, Topfen!",
            "Vero. Da noi si dice Semmel, non Brötchen. E Paradeiser per pomodori." to "True. Where we're from we say Semmel, not Brötchen. And Paradeiser for tomatoes.",
            "Esatto. In ambulatorio i pazienti dicono spesso 'Jänner' invece di Januar." to "Exactly. At the clinic patients often say 'Jänner' instead of Januar.",
            "Non importa. L'importante è capirsi. Cin cin!" to "It doesn't matter. The important thing is understanding each other. Cheers!",
            "Cin cin! Alle patate!" to "Cheers! To potatoes!",
            "Allora, le mostro gli esercizi da fare a casa per il ginocchio." to "So, I'll show you the exercises to do at home for your knee.",
            "Quanto spesso devo farli?" to "How often should I do them?",
            "Tre volte al giorno. Mattina, mezzogiorno, sera. Dieci ripetizioni ciascuna." to "Three times a day. Morning, noon, evening. Ten repetitions each.",
            "E se fa male? Devo smettere?" to "And if it hurts? Should I stop?",
            "Un leggero dolore va bene. Ma dolore acuto: smetta subito." to "Mild pain is fine. But sharp pain: stop immediately.",
            "Capito. Quando è il controllo?" to "Understood. When is the follow-up?",
            "Tra due settimane. Porti il diario dove segna gli esercizi." to "In two weeks. Bring the diary where you record the exercises.",
            "Tutto chiaro. Grazie, signor Müller." to "All clear. Thank you, Mr Müller.",
            "Buona guarigione! E ricordi: il movimento è la migliore medicina." to "Get well soon! And remember: movement is the best medicine.",
            "Ciao! È anche lei qui nel corso di tedesco?" to "Hi! Are you also here in the German course?",
            "Sì, sono nuovo qui. Mi chiamo Sophie. E tu?" to "Yes, I'm new here. My name is Sophie. And you?",
            "Sono Thomas, molto piacere. Da dove vieni?" to "I'm Thomas, nice to meet you. Where are you from?",
            "Vengo da Bressanone. E tu?" to "I'm from Brixen. And you?",
            "Anche io da Bressanone! Perché studi tedesco?" to "I'm also from Brixen! Why are you learning German?",
            "Per il lavoro e per l'esame. E tu?" to "For work and for the exam. And you?",
            "Per il mio lavoro in ospedale. Il corso è ogni martedì." to "For my work at the hospital. The course is every Tuesday.",
            "Buongiorno, cosa posso fare per lei?" to "Good morning, what can I do for you?",
            "Buongiorno. Ho il raffreddore e mal di testa." to "Good morning. I have a cold and a headache.",
            "Da quando ha i sintomi?" to "How long have you had the symptoms?",
            "Da tre giorni. Di notte dormo male." to "For three days. I sleep badly at night.",
            "Le consiglio queste gocce e una crema contro il dolore." to "I recommend these drops and a pain relief cream.",
            "Ogni quanto devo prendere le gocce?" to "How often should I take the drops?",
            "Tre volte al giorno, dopo i pasti. Migliorie!" to "Three times a day, after meals. Get well soon!",
            "Scusi, dove trovo il pane e il latte?" to "Excuse me, where can I find bread and milk?",
            "Il pane è nel reparto panetteria, in fondo a sinistra. Il latte nei frigo dei latticini." to "The bread is in the bakery section, at the back on the left. The milk is in the dairy fridges.",
            "Grazie mille. E quanto costa la ciabatta?" to "Thank you very much. And how much does the roll cost?",
            "40 centesimi l'uno. Oggi c'è una promozione: tre per un euro." to "40 cents each. Today there's a promotion: three for one euro.",
            "Bene, allora ne prendo tre. Da dove viene il formaggio?" to "Great, then I'll take three. Where does the cheese come from?",
            "Da una latteria in Alto Adige — un ottimo prodotto!" to "From a dairy in South Tyrol — an excellent product!",
            "Allora ne prendo anche 200 grammi. Grazie mille." to "Then I'll take 200 grams as well. Thank you very much.",
            "Buongiorno, signora Huber. Cosa la porta oggi da me?" to "Good morning, Ms Huber. What brings you here today?",
            "Ho mal di schiena da una settimana, a sinistra sotto la spalla." to "I've had back pain for a week, on the left below the shoulder.",
            "Febbre? Tosse? Perdita di peso?" to "Fever? Cough? Weight loss?",
            "No, niente. Ma di notte mi sveglio." to "No, nothing. But I wake up at night.",
            "Le prescrivo un antidolorifico e un'impegnativa per la fisioterapia." to "I'll prescribe you a painkiller and a referral for physiotherapy.",
            "Per quanto tempo devo prendere le compresse?" to "How long do I need to take the tablets?",
            "Quattro giorni, al massimo due volte al giorno. Se non migliora, torni da me." to "Four days, maximum twice a day. If it doesn't improve, come back to me.",
            "Buongiorno, si sieda per favore. Quale dente fa male?" to "Good morning, please have a seat. Which tooth hurts?",
            "In basso a destra, il molare. Quando mastico fa male, soprattutto." to "Bottom right, the molar. It hurts especially when I chew.",
            "Apra la bocca per favore. ... Sì, vedo una piccola carie." to "Please open your mouth. ... Yes, I see a small cavity.",
